INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C1','kor',2,1,'u4',1,'겹받침 알기 — 닭(ㄺ)·값(ㅄ)·앉다(ㄵ)처럼 받침 자리에 서로 다른 글자가 두 개 있는 받침을 알고, 홑받침·쌍받침 낱말과 가려 겹받침 낱말 찾기',ARRAY['2국04-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C2','kor',2,1,'u4',3,'겹받침 낱말 바르게 읽기 — 겹받침은 두 글자 가운데 한 글자의 소리로 읽고(ㄺ·ㄳ → [ㄱ], ㄵ → [ㄴ], ㄼ → [ㄹ], ㄻ → [ㅁ], ㅄ → [ㅂ]), 뒤 글자 소리가 바뀌는 것(앉다[안따]·많다[만타])까지 살려 읽기',ARRAY['2국04-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C3','kor',2,1,'u4',3,'겹받침 낱말 바르게 쓰기 — 읽는 소리와 쓰는 글자가 다를 수 있음을 알고, [닥]·[갑]으로 들려도 「닭」·「값」처럼 받침 두 글자를 모두 살려 쓰기(앉다↔않다처럼 받침 짝 가리기)',ARRAY['2국04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C4','kor',2,1,'u4',6,'글 속 겹받침 낱말 읽기 — 글을 읽다가 겹받침 낱말이 나오면 잠깐 멈춰 바른 소리를 떠올려 읽고, 바르게 읽으며 글의 내용도 함께 이해하기',ARRAY['2국04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C5','kor',2,1,'u4',1,'분위기의 뜻 — 분위기는 글이나 시를 읽을 때 느껴지는 기분(신나는·조용한·포근한·씩씩한)이며, 분위기를 살려 읽으면 작품이 더 재미있게 전해짐을 알기',ARRAY['2국05-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C6','kor',2,1,'u4',8,'말과 장면으로 시의 분위기 찾기 — 시에 나오는 말(통통·콩콩·살며시·소복소복)과 장면(운동장·달밤·봄볕)을 살펴 분위기를 찾고, 그렇게 느낀 까닭을 말하기',ARRAY['2국05-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C7','kor',2,1,'u4',10,'분위기에 알맞게 소리 내어 읽기 — 신나는 시는 밝고 빠르게, 조용한 시는 천천히 부드럽게, 씩씩한 시는 또렷하고 힘차게, 포근한 시는 다정하고 따뜻하게 — 목소리 크기와 빠르기를 분위기에 맞추기',ARRAY['2국05-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C8','kor',2,1,'u4',10,'알맞게 띄어 읽기 — 뜻이 이어지는 말끼리 묶어 한 덩어리씩 읽고, 「/」에서는 조금 쉬고 「//」에서는 조금 더 쉬어 뜻이 잘 드러나게 읽기',ARRAY['2국02-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C9','kor',2,1,'u4',12,'시 낭송하기 — 마음에 드는 시 고르기 → 분위기를 살펴 읽는 방법 정해 연습하기 → 친구들 앞에서 또렷하게 분위기를 살려 낭송하기',ARRAY['2국05-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u4-C10','kor',2,1,'u4',12,'시를 나누며 듣기 — 친구가 낭송할 때 조용히 끝까지 들으며 장면을 떠올리고, 끝나면 박수와 칭찬으로 반응하며, 시를 나누면 여러 분위기와 친구 마음을 만날 수 있음을 알기',ARRAY['2국05-01']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X01','kor',2,'u4',ARRAY['K2-1-u4-C3']::text[],'들리는 소리대로 받침을 하나만 쓴다([닥] → 닥, [갑] → 갑, [안따] → 안따)','받침 자리에 글자가 두 개 다 있는지 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X02','kor',2,'u4',ARRAY['K2-1-u4-C2','K2-1-u4-C4']::text[],'겹받침 두 글자를 모두 소리 내거나 글자 그대로 읽는다(닭 → [달ㄱ], 값 → [갑ㅅ])','겹받침은 「둘 중 하나」 — 한 소리만 내는지 다시 읽어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X03','kor',2,'u4',ARRAY['K2-1-u4-C2','K2-1-u4-C4']::text[],'겹받침 두 글자 가운데 다른 쪽 글자의 소리로 읽는다(닭 → [달], 넓다 → [넙따], 값 → [갓])','ㄺ은 [ㄱ], ㄼ은 [ㄹ], ㅄ은 [ㅂ] — 받침 소리 짝을 소리 내어 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X04','kor',2,'u4',ARRAY['K2-1-u4-C2']::text[],'겹받침 뒤 글자의 소리가 바뀌는 것을 놓친다(앉다 → [안다], 넓다 → [널다], 많다 → [만다])','「따·타」처럼 뒤 글자가 세게 나는지 귀 기울여 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X05','kor',2,'u4',ARRAY['K2-1-u4-C1','K2-1-u4-C4']::text[],'겹받침과 홑받침·쌍받침을 가리지 못한다(산·손·있다·밖을 겹받침으로 여기거나, 닭의 받침을 ㄱ 하나로 안다)','받침 자리에 「서로 다른」 글자가 두 개인지 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X06','kor',2,'u4',ARRAY['K2-1-u4-C3']::text[],'겹받침의 글자 짝을 잘못 쓴다(닭 → 닯, 앉다 → 않다, 값 → 갋)','뜻을 떠올리고 받침 두 글자를 하나씩 소리 내며 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X07','kor',2,'u4',ARRAY['K2-1-u4-C4','K2-1-u4-C6']::text[],'글에 없는 내용을 있다고 하거나, 겹받침 낱말에만 매달려 글의 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X08','kor',2,'u4',ARRAY['K2-1-u4-C5']::text[],'분위기를 글의 줄거리·등장인물·글자 수·제목으로 여긴다','「읽고 나서 어떤 기분이 들었지?」 하고 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X09','kor',2,'u4',ARRAY['K2-1-u4-C6']::text[],'시에 나오는 말과 장면을 살피지 않고 분위기를 엉뚱하게 고르거나, 소재만 보고 분위기를 정한다(눈 → 언제나 조용함)','시에서 기분을 만드는 말에 동그라미 치고 장면을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X10','kor',2,'u4',ARRAY['K2-1-u4-C6']::text[],'분위기를 나타내는 말의 느낌을 바꿔 안다(살며시·소복소복 → 신나는, 통통·콩콩 → 조용한)','그 말을 소리 내어 따라 하며 몸이 어떤 기분이 드는지 느끼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X11','kor',2,'u4',ARRAY['K2-1-u4-C7','K2-1-u4-C9']::text[],'모든 글을 한 가지 목소리로 읽거나, 분위기와 맞지 않는 목소리로 읽는다(조용한 시를 크게 소리 지르며)','「이 시의 기분에 어울리는 목소리는?」 먼저 정하고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X12','kor',2,'u4',ARRAY['K2-1-u4-C7']::text[],'빠르고 크게 읽으면 언제나 잘 읽은 것으로 여긴다','빠르기도 분위기에 맞추는 것 — 천천히 읽어야 할 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X13','kor',2,'u4',ARRAY['K2-1-u4-C8']::text[],'한 글자씩 끊거나 아무 데서나 띄어 읽어 뜻이 드러나지 않는다(달 / 님이살 / 며시)','뜻이 이어지는 말끼리 손으로 묶어 보고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X14','kor',2,'u4',ARRAY['K2-1-u4-C8']::text[],'띄어 읽기 표시의 뜻을 바꿔 안다(「//」를 덜 쉬거나 「/」에서 쉬지 않음)','「/」 한 번 쉬고, 「//」 한 번 더 쉬기 — 손뼉으로 쉬는 길이 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X15','kor',2,'u4',ARRAY['K2-1-u4-C9']::text[],'낭송 차례를 뒤바꾸거나(연습 없이 낭송), 장난치며·작게 우물우물·외우기만 하며 낭송한다','「고르기 → 연습하기 → 낭송하기」 차례와 「또렷하게·분위기 살려」 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X16','kor',2,'u4',ARRAY['K2-1-u4-C10']::text[],'친구가 낭송할 때 떠들거나 딴짓하고, 중간에 끼어들거나 놀린다','「내가 낭송할 때 친구가 어떻게 들어 주면 좋을까?」 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u4-X17','kor',2,'u4',ARRAY['K2-1-u4-C1','K2-1-u4-C2','K2-1-u4-C3','K2-1-u4-C4','K2-1-u4-C6','K2-1-u4-C7','K2-1-u4-C8','K2-1-u4-C9','K2-1-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 알맞지 않은↔알맞은, 잘못↔바르게','물음의 「아닌·않은·잘못」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#1','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"산","mis":"K2-1-u4-X05"},{"t":"손","mis":"K2-1-u4-X05"}],"explanation":["「닭」은 받침 자리에 ㄹ과 ㄱ, 두 글자가 있어요.","「산」·「손」은 받침이 ㄴ 하나뿐이에요.","이런 받침을 겹받침이라고 해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"감","mis":"K2-1-u4-X05"},{"t":"강","mis":"K2-1-u4-X05"}],"explanation":["「값」은 받침 자리에 ㅂ과 ㅅ, 두 글자가 있어요.","「감」·「강」은 받침이 하나뿐이에요.","이런 받침을 겹받침이라고 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#2','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',1,'mc','auto','「흙」의 받침은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":2,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"「흙」의 받침은 어느 것인가요?","options":[{"t":"ㄺ","correct":true},{"t":"ㄱ","mis":"K2-1-u4-X05"},{"t":"ㄹ","mis":"K2-1-u4-X05"}],"explanation":["「흙」의 받침 자리에는 ㄹ과 ㄱ이 함께 있어요.","ㄱ이나 ㄹ 하나만 고르면 받침 글자 하나를 빠뜨린 거예요.","받침 자리의 글자를 모두 짚어 봐요."],"variant_rule":{"alt":[{"stem":"「앉다」의 「앉」 받침은 어느 것인가요?","options":[{"t":"ㄵ","correct":true},{"t":"ㄴ","mis":"K2-1-u4-X05"},{"t":"ㅈ","mis":"K2-1-u4-X05"}],"explanation":["「앉」의 받침 자리에는 ㄴ과 ㅈ이 함께 있어요.","ㄴ이나 ㅈ 하나만 고르면 받침 글자 하나를 빠뜨린 거예요.","받침 자리의 글자를 모두 짚어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#3','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C5',1,'mc','auto','글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?',ARRAY['K2-1-u4-X08']::text[],true,'{"seq":3,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"제목","mis":"K2-1-u4-X08"},{"t":"겹받침","mis":"K2-1-u4-X08"}],"explanation":["글이나 시에서 느껴지는 기분을 분위기라고 해요.","제목은 글의 이름, 겹받침은 받침의 한 가지예요.","신나는 분위기, 조용한 분위기처럼 말해요."],"variant_rule":{"alt":[{"stem":"「분위기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글이나 시를 읽을 때 느껴지는 기분","correct":true},{"t":"글에 나오는 사람의 이름","mis":"K2-1-u4-X08"},{"t":"글에 있는 글자의 수","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시에서 느껴지는 기분이에요.","사람 이름이나 글자 수는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#4','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C2',1,'ox','auto','「닭」은 받침 글자 두 개를 모두 소리 내어 [달ㄱ]처럼 읽어요.',ARRAY['K2-1-u4-X02']::text[],true,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":1,"kind":"ox","stem":"「닭」은 받침 글자 두 개를 모두 소리 내어 [달ㄱ]처럼 읽어요.","answer":"X","reason_options":[{"t":"겹받침은 둘 중 한 소리로 [닥]이라고 읽으니까","correct":true},{"t":"받침 글자는 모두 소리 내야 하니까","mis":"K2-1-u4-X02"}],"mis":"K2-1-u4-X02","explanation":["「닭」은 [닥]이라고 읽어요.","겹받침은 두 글자 가운데 한 글자의 소리만 나요.","글자와 소리가 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"「값」은 [갑]이라고 읽어요.","answer":"O","reason_options":[{"t":"ㅄ 받침은 [ㅂ] 소리로 읽으니까","correct":true},{"t":"받침 글자 두 개를 모두 소리 내니까","mis":"K2-1-u4-X02"}],"explanation":["「값」은 [갑]이라고 읽어요.","겹받침은 두 글자 가운데 한 글자의 소리만 나요.","글자와 소리가 다를 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#5','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"닭","r":"[닥]"},{"l":"값","r":"[갑]"},{"l":"흙","r":"[흑]"}],"mis":"K2-1-u4-X03","explanation":["「닭」은 [닥]이라고 읽어요.","「값」은 [갑]이라고 읽어요.","「흙」은 [흑]이라고 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"앉다","r":"[안따]"},{"l":"넓다","r":"[널따]"},{"l":"맑다","r":"[막따]"}],"explanation":["「앉다」는 [안따]라고 읽어요.","「넓다」는 [널따]라고 읽어요.","「맑다」는 [막따]라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#6','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',2,'mc','auto','겹받침이 있는 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":6,"concept":"K2-1-u4-C1","difficulty":2,"kind":"mc","stem":"겹받침이 있는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"닭 · 값 · 흙","correct":true},{"t":"닭 · 산 · 흙","mis":"K2-1-u4-X05"},{"t":"손 · 강 · 밤","mis":"K2-1-u4-X05"}],"explanation":["「닭」·「값」·「흙」은 모두 받침 자리에 글자가 두 개 있어요.","「산」·「손」·「강」·「밤」은 받침이 하나예요.","받침 자리의 글자 수를 세어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 겹받침이 있는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"앉다 · 짧다 · 읽다","correct":true},{"t":"앉다 · 바다 · 읽다","mis":"K2-1-u4-X05"},{"t":"구름 · 바다 · 나무","mis":"K2-1-u4-X05"}],"explanation":["「앉다」·「짧다」·「읽다」의 첫 글자는 모두 겹받침이 있어요.","「바다」·「나무」는 받침이 없고, 「구름」은 받침이 하나예요.","받침 자리의 글자 수를 세어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#7','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C5',2,'mc','auto','시를 읽고 답해 보세요. 이 시에서 느껴지는 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],true,'{"seq":7,"concept":"K2-1-u4-C5","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시에서 느껴지는 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"무서운","mis":"K2-1-u4-X09"},{"t":"슬픈","mis":"K2-1-u4-X09"}],"explanation":["「톡톡」·「첨벙첨벙」·「랄랄라」가 신나는 기분을 줘요.","무섭거나 슬픈 말은 시에 없어요.","시에 나오는 말에서 기분을 느껴 봐요."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시에서 느껴지는 분위기는 어느 것인가요?","options":[{"t":"조용한","correct":true},{"t":"시끄러운","mis":"K2-1-u4-X09"},{"t":"화난","mis":"K2-1-u4-X09"}],"explanation":["「살며시」·「쉿」·「새근새근」이 조용한 기분을 줘요.","시끄럽거나 화난 말은 시에 없어요.","시에 나오는 말에서 기분을 느껴 봐요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#8','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',2,'sa','auto','받침 자리에 서로 다른 글자가 두 개 있는 받침을 무엇이라고 하나요? 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u4-C1","difficulty":2,"kind":"sa","stem":"받침 자리에 서로 다른 글자가 두 개 있는 받침을 무엇이라고 하나요? 세 글자로 써 보세요.","answer":["겹받침"],"explanation":["「닭」의 ㄺ, 「값」의 ㅄ 같은 받침을 겹받침이라고 해요.","받침 글자가 하나인 받침과 달라요.","읽을 때는 한 소리로 읽어요."],"variant_rule":{"alt":[{"stem":"「앉다」의 ㄵ, 「짧다」의 ㄼ처럼 받침 자리에 서로 다른 글자가 두 개 있는 받침을 무엇이라고 하나요? 세 글자로 써 보세요.","answer":["겹받침"],"explanation":["ㄵ·ㄼ처럼 두 글자가 함께 있는 받침을 겹받침이라고 해요.","받침 글자가 하나인 받침과 달라요.","읽을 때는 한 소리로 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#9','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C5',2,'mc','auto','분위기를 살려 읽으면 어떤 점이 좋을까요?',ARRAY['K2-1-u4-X12','K2-1-u4-X08']::text[],true,'{"seq":9,"concept":"K2-1-u4-C5","difficulty":2,"kind":"mc","stem":"분위기를 살려 읽으면 어떤 점이 좋을까요?","options":[{"t":"글의 기분이 살아나 더 재미있게 느껴져요","correct":true},{"t":"글자를 더 빨리 읽을 수 있어요","mis":"K2-1-u4-X12"},{"t":"글의 내용이 다른 이야기로 바뀌어요","mis":"K2-1-u4-X08"}],"explanation":["분위기를 살려 읽으면 글의 기분이 잘 전해져요.","빨리 읽거나 내용을 바꾸는 것이 아니에요.","듣는 사람도 더 재미있게 느껴요."],"variant_rule":{"alt":[{"stem":"같은 시라도 분위기를 살려 읽으면 어떻게 될까요?","options":[{"t":"시의 기분이 듣는 사람에게 더 잘 전해져요","correct":true},{"t":"시의 글자가 바뀌어요","mis":"K2-1-u4-X08"},{"t":"시가 더 짧아져요","mis":"K2-1-u4-X08"}],"explanation":["분위기를 살려 읽으면 시의 기분이 잘 전해져요.","글자나 길이가 바뀌는 것이 아니에요.","그래서 시가 더 재미있게 느껴져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_basic#10','kor',2,1,'u4','L01','g2_1_kor_u4_L01_basic','lesson_basic','K2-1-u4-C1',3,'error','auto','「마당에 닭이 앉아 흙을 쪼아요.」에서 겹받침이 있는 글자를 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u4-X05','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C1","difficulty":3,"kind":"error","stem":"「마당에 닭이 앉아 흙을 쪼아요.」에서 겹받침이 있는 글자를 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"하린 — 「당」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"도윤 — 「닭」","mis":"K2-1-u4-X17"},{"t":"서아 — 「흙」","mis":"K2-1-u4-X17"}],"explanation":["「당」은 받침이 ㅇ 하나뿐이에요.","「닭」·「앉」·「흙」이 겹받침이 있는 글자예요.","도윤이와 서아는 바르게 찾았어요."],"variant_rule":{"alt":[{"stem":"「하늘이 맑아 넓은 들판에 앉았어요.」에서 겹받침이 있는 글자를 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"준우 — 「늘」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"지안 — 「맑」","mis":"K2-1-u4-X17"},{"t":"예린 — 「넓」","mis":"K2-1-u4-X17"}],"explanation":["「늘」은 받침이 ㄹ 하나뿐이에요.","「맑」·「넓」·「앉」이 겹받침이 있는 글자예요.","지안이와 예린이는 바르게 찾았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#1','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',2,'mc','auto','ㄲ·ㅆ처럼 같은 글자가 두 개인 받침은 겹받침이 아니에요. 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":2,"kind":"mc","stem":"ㄲ·ㅆ처럼 같은 글자가 두 개인 받침은 겹받침이 아니에요. 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"읽다","correct":true},{"t":"있다","mis":"K2-1-u4-X05"},{"t":"밖","mis":"K2-1-u4-X05"}],"explanation":["「읽다」의 받침 ㄺ은 서로 다른 두 글자예요.","「있다」의 ㅆ, 「밖」의 ㄲ은 같은 글자가 두 개예요.","겹받침은 서로 다른 두 글자가 함께 있는 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#2','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C5',2,'mc','auto','분위기에 대해 바르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":2,"concept":"K2-1-u4-C5","difficulty":2,"kind":"mc","stem":"분위기에 대해 바르게 말한 친구는 누구인가요?","options":[{"t":"지호 — 「시에 나오는 말과 장면에서 분위기를 느낄 수 있어.」","correct":true},{"t":"민지 — 「분위기는 시에 나오는 사람 이름이야.」","mis":"K2-1-u4-X08"},{"t":"하준 — 「분위기는 글자가 많을수록 신나.」","mis":"K2-1-u4-X08"}],"explanation":["시의 말과 장면이 기분을 만들어요.","사람 이름이나 글자 수는 분위기가 아니에요.","지호가 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#3','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','겹받침 낱말을 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X03']::text[],false,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"겹받침 낱말을 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"받침 두 글자 가운데 한 글자의 소리로 읽어요","correct":true},{"t":"받침 두 글자를 모두 소리 내어 읽어요","mis":"K2-1-u4-X02"},{"t":"받침 두 글자 가운데 아무 쪽이나 골라 읽어요","mis":"K2-1-u4-X03"}],"explanation":["겹받침은 정해진 한 글자의 소리로 읽어요.","두 글자를 다 소리 내면 틀려요.","아무 쪽이나가 아니라 ㄺ은 [ㄱ], ㄼ은 [ㄹ]처럼 정해져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#4','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C2',3,'error','auto','낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"시우 — 「흙 → [흘]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"다은 — 「닭 → [닥]」","mis":"K2-1-u4-X17"},{"t":"로아 — 「값 → [갑]」","mis":"K2-1-u4-X17"}],"explanation":["「흙」은 [흑]이라고 읽어요.","ㄺ 받침은 [ㄱ] 소리가 나요.","다은이와 로아는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#5','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',3,'ox','auto','「손」과 「산」에는 겹받침이 있어요.',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":5,"concept":"K2-1-u4-C1","difficulty":3,"kind":"ox","stem":"「손」과 「산」에는 겹받침이 있어요.","answer":"X","reason_options":[{"t":"받침이 ㄴ 하나뿐이니까","correct":true},{"t":"받침이 있으면 모두 겹받침이니까","mis":"K2-1-u4-X05"}],"mis":"K2-1-u4-X05","explanation":["「손」·「산」의 받침은 ㄴ 하나예요.","받침 자리에 서로 다른 글자가 두 개 있어야 겹받침이에요.","「닭」·「값」과 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#6','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C5',3,'mc','auto','두 시를 읽고 분위기를 바르게 짝지은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#7','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',3,'mc','auto','「여덟 개의 사과가 바구니에 많이 있어요.」에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":7,"concept":"K2-1-u4-C1","difficulty":3,"kind":"mc","stem":"「여덟 개의 사과가 바구니에 많이 있어요.」에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?","options":[{"t":"덟 · 많","correct":true},{"t":"덟 · 많 · 있","mis":"K2-1-u4-X05"},{"t":"사 · 과","mis":"K2-1-u4-X05"}],"explanation":["「덟」은 ㄼ, 「많」은 ㄶ 받침이에요.","「있」의 ㅆ은 같은 글자가 두 개라 겹받침이 아니에요.","「사」·「과」는 받침이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#8','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C2',4,'mc','auto','「짧다」를 [짭따]라고 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X04']::text[],false,'{"seq":8,"concept":"K2-1-u4-C2","difficulty":4,"kind":"mc","stem":"「짧다」를 [짭따]라고 읽은 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「ㄼ 받침은 [ㄹ] 소리가 나서 [짤따]라고 읽어.」","correct":true},{"t":"「받침 두 글자를 다 살려 [짤ㅂ다]라고 읽어.」","mis":"K2-1-u4-X02"},{"t":"「뒤 글자는 그대로 두고 [짤다]라고 읽어.」","mis":"K2-1-u4-X04"}],"explanation":["「짧다」는 [짤따]라고 읽어요.","두 글자를 다 소리 내면 안 돼요.","뒤 글자 「다」는 [따]로 세게 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#9','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C1',4,'essay','teacher','겹받침이 무엇인지 쓰고, 겹받침이 있는 낱말을 두 개 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C1","difficulty":4,"kind":"essay","stem":"겹받침이 무엇인지 쓰고, 겹받침이 있는 낱말을 두 개 써 보세요.","answer_guide":{"answer":"예: 겹받침은 받침 자리에 서로 다른 글자가 두 개 있는 받침이에요. 닭, 값.","scoring_points":["받침 자리에 서로 다른 글자가 두 개라고 썼는가","겹받침 낱말을 두 개 썼는가","쓴 낱말이 홑받침·쌍받침 낱말이 아닌가"]},"explanation":["겹받침의 뜻.","겹받침 낱말 두 개.","홑받침·쌍받침과 가리기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L01_challenge#10','kor',2,1,'u4','L01','g2_1_kor_u4_L01_challenge','lesson_challenge','K2-1-u4-C5',4,'essay','teacher','분위기가 무엇인지 쓰고, 신나는 분위기와 조용한 분위기가 느껴지는 장면을 하나씩 떠올려 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C5","difficulty":4,"kind":"essay","stem":"분위기가 무엇인지 쓰고, 신나는 분위기와 조용한 분위기가 느껴지는 장면을 하나씩 떠올려 써 보세요.","answer_guide":{"answer":"예: 분위기는 글이나 시에서 느껴지는 기분이에요. 신나는 분위기 — 운동장에서 친구들과 공을 차는 장면. 조용한 분위기 — 아기가 새근새근 자는 밤.","scoring_points":["분위기의 뜻을 썼는가","신나는 장면을 알맞게 썼는가","조용한 장면을 알맞게 썼는가"]},"explanation":["분위기의 뜻.","신나는 장면.","조용한 장면."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#1','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',1,'mc','auto','「앉다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X03']::text[],true,'{"seq":1,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「앉다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[안따]","correct":true},{"t":"[안다]","mis":"K2-1-u4-X04"},{"t":"[앚따]","mis":"K2-1-u4-X03"}],"explanation":["ㄵ 받침은 [ㄴ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[안다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요.","[앚따]는 다른 쪽 글자 소리로 읽었어요."],"variant_rule":{"alt":[{"stem":"「넓다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[널따]","correct":true},{"t":"[넙따]","mis":"K2-1-u4-X03"},{"t":"[널다]","mis":"K2-1-u4-X04"}],"explanation":["ㄼ 받침은 [ㄹ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[넙따]는 다른 쪽 글자 소리로 읽었어요.","[널다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#2','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',1,'mc','auto','[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],true,'{"seq":2,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K2-1-u4-X01"},{"t":"갋","mis":"K2-1-u4-X06"}],"explanation":["[갑]으로 들려도 받침 두 글자를 살려 「값」이라고 써요.","「갑」은 소리 나는 대로 받침을 하나만 썼어요.","「갋」은 받침 짝을 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"[닥]이라고 소리 나는, 「꼬끼오」 하고 우는 동물을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K2-1-u4-X01"},{"t":"닯","mis":"K2-1-u4-X06"}],"explanation":["[닥]으로 들려도 받침 두 글자를 살려 「닭」이라고 써요.","「닥」은 소리 나는 대로 받침을 하나만 썼어요.","「닯」은 받침 짝을 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#3','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',1,'ox','auto','「흙」은 [흑]이라고 소리 나니까 「흑」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],true,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"ox","stem":"「흙」은 [흑]이라고 소리 나니까 「흑」이라고 써요.","answer":"X","reason_options":[{"t":"소리는 하나여도 쓸 때는 받침 두 글자를 모두 살려 쓰니까","correct":true},{"t":"들리는 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「흙」은 [흑]으로 읽지만 「흙」이라고 써요.","소리대로 쓰면 다른 글자가 돼요.","읽을 때와 쓸 때를 가려 기억해요."],"variant_rule":{"alt":[{"stem":"「닭」은 [닥]이라고 읽지만 쓸 때는 「닭」이라고 써요.","answer":"O","reason_options":[{"t":"읽는 소리와 쓰는 글자가 다를 수 있으니까","correct":true},{"t":"쓸 때도 소리대로 「닥」이라고 써야 하니까","mis":"K2-1-u4-X01"}],"explanation":["「닭」은 [닥]으로 읽고 「닭」으로 써요.","받침 두 글자를 모두 살려 써요.","읽을 때와 쓸 때를 가려 기억해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#4','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',1,'mc','auto','「맑다」의 ㄺ 받침은 어떤 소리로 읽나요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],true,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「맑다」의 ㄺ 받침은 어떤 소리로 읽나요?","options":[{"t":"[ㄱ] 소리","correct":true},{"t":"[ㄹ] 소리","mis":"K2-1-u4-X03"},{"t":"[ㄹ]과 [ㄱ] 소리 모두","mis":"K2-1-u4-X02"}],"explanation":["「맑다」는 [막따]라고 읽어요.","ㄺ 받침은 [ㄱ] 소리가 나요.","두 소리를 모두 내지 않아요."],"variant_rule":{"alt":[{"stem":"「짧다」의 ㄼ 받침은 어떤 소리로 읽나요?","options":[{"t":"[ㄹ] 소리","correct":true},{"t":"[ㅂ] 소리","mis":"K2-1-u4-X03"},{"t":"[ㄹ]과 [ㅂ] 소리 모두","mis":"K2-1-u4-X02"}],"explanation":["「짧다」는 [짤따]라고 읽어요.","ㄼ 받침은 [ㄹ] 소리가 나요.","두 소리를 모두 내지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#5','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"많다","r":"[만타]"},{"l":"읽다","r":"[익따]"},{"l":"짧다","r":"[짤따]"}],"mis":"K2-1-u4-X03","explanation":["「많다」는 [만타]라고 읽어요.","「읽다」는 [익따]라고 읽어요.","「짧다」는 [짤따]라고 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"없다","r":"[업따]"},{"l":"젊다","r":"[점따]"},{"l":"맑다","r":"[막따]"}],"explanation":["「없다」는 [업따]라고 읽어요.","「젊다」는 [점따]라고 읽어요.","「맑다」는 [막따]라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#6','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',2,'blank','auto','「의자에 (     ) 이야기를 들어요.」 [안자]라고 소리 나는 말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],true,'{"seq":6,"concept":"K2-1-u4-C3","difficulty":2,"kind":"blank","stem":"「의자에 (     ) 이야기를 들어요.」 [안자]라고 소리 나는 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"앉아","correct":true},{"t":"안자","mis":"K2-1-u4-X01"},{"t":"않아","mis":"K2-1-u4-X06"}],"explanation":["엉덩이를 대고 몸을 올려놓는 것은 「앉아」라고 써요.","「안자」는 소리 나는 대로 썼어요.","「않아」는 받침 짝이 달라 뜻이 다른 말이 돼요."],"variant_rule":{"alt":[{"stem":"「동생 바지가 조금 (     ).」 [짤바요]라고 소리 나는 말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"짧아요","correct":true},{"t":"짤바요","mis":"K2-1-u4-X01"},{"t":"짭아요","mis":"K2-1-u4-X06"}],"explanation":["길이가 길지 않은 것은 「짧아요」라고 써요.","「짤바요」는 소리 나는 대로 썼어요.","「짭아요」는 받침 글자를 하나 빠뜨리고 다르게 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#7','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',2,'sa','auto','[흑]이라고 소리 나는, 식물을 심는 땅의 겉 부분을 바르게 써 보세요.','{}'::text[],true,'{"seq":7,"concept":"K2-1-u4-C3","difficulty":2,"kind":"sa","stem":"[흑]이라고 소리 나는, 식물을 심는 땅의 겉 부분을 바르게 써 보세요.","answer":["흙"],"explanation":["[흑]으로 들려도 「흙」이라고 써요.","받침 자리에 ㄹ과 ㄱ을 모두 써요.","「흑」이라고 쓰면 틀려요."],"variant_rule":{"alt":[{"stem":"[갑]이라고 소리 나는 말이에요. 「이 연필의 (     )은 얼마예요?」 빈칸에 들어갈 말을 바르게 써 보세요.","answer":["값"],"explanation":["[갑]으로 들려도 「값」이라고 써요.","받침 자리에 ㅂ과 ㅅ을 모두 써요.","「갑」이라고 쓰면 틀려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#8','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',2,'mc','auto','「읽다」를 [일따]라고 읽은 친구가 있어요. 바르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X04']::text[],true,'{"seq":8,"concept":"K2-1-u4-C2","difficulty":2,"kind":"mc","stem":"「읽다」를 [일따]라고 읽은 친구가 있어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"[익따]","correct":true},{"t":"[읽따]","mis":"K2-1-u4-X02"},{"t":"[익다]","mis":"K2-1-u4-X04"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나서 [익따]예요.","[읽따]는 두 글자를 다 살리려 한 거예요.","[익다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."],"variant_rule":{"alt":[{"stem":"「없다」를 [엇따]라고 읽은 친구가 있어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"[업따]","correct":true},{"t":"[없따]","mis":"K2-1-u4-X02"},{"t":"[업다]","mis":"K2-1-u4-X04"}],"explanation":["ㅄ 받침은 [ㅂ] 소리가 나서 [업따]예요.","[없따]는 두 글자를 다 살리려 한 거예요.","[업다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#9','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C2',2,'ox','auto','「넓다」와 「짧다」는 받침이 똑같이 [ㄹ] 소리로 나요.',ARRAY['K2-1-u4-X02']::text[],true,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"ox","stem":"「넓다」와 「짧다」는 받침이 똑같이 [ㄹ] 소리로 나요.","answer":"O","reason_options":[{"t":"두 낱말 모두 ㄼ 받침이라 [널따]·[짤따]로 읽으니까","correct":true},{"t":"받침 글자가 같으면 두 소리를 모두 내니까","mis":"K2-1-u4-X02"}],"mis":"K2-1-u4-X02","explanation":["「넓다」는 [널따], 「짧다」는 [짤따]예요.","ㄼ 받침은 [ㄹ] 소리가 나요.","받침이 같으면 소리 나는 방법도 같아요."],"variant_rule":{"alt":[{"stem":"「닭」과 「흙」은 받침이 [ㄹ] 소리로 나요.","answer":"X","reason_options":[{"t":"ㄺ 받침은 [ㄱ] 소리라 [닥]·[흑]으로 읽으니까","correct":true},{"t":"ㄺ의 앞 글자가 ㄹ이니까","mis":"K2-1-u4-X03"}],"explanation":["「닭」은 [닥], 「흙」은 [흑]이에요.","ㄺ 받침은 [ㄱ] 소리가 나요.","앞 글자라고 그 소리가 나는 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_basic#10','kor',2,1,'u4','L03','g2_1_kor_u4_L03_basic','lesson_basic','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「흑 위에 꽃씨를 심었다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"다은 — 「연필 값이 비싸다.」","mis":"K2-1-u4-X17"},{"t":"시우 — 「의자에 앉았다.」","mis":"K2-1-u4-X17"}],"explanation":["「흑」은 소리대로 쓴 거예요. 「흙」이라고 써야 해요.","다은이와 시우는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「사과가 여덜 개 있다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"예린 — 「동화책을 읽었다.」","mis":"K2-1-u4-X17"},{"t":"소율 — 「운동장이 넓다.」","mis":"K2-1-u4-X17"}],"explanation":["「여덜」은 소리대로 쓴 거예요. 「여덟」이라고 써야 해요.","예린이와 소율이는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#1','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',2,'mc','auto','「사과가 (     ) 개 있어요.」 [여덜]이라고 소리 나는 수를 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":1,"concept":"K2-1-u4-C3","difficulty":2,"kind":"mc","stem":"「사과가 (     ) 개 있어요.」 [여덜]이라고 소리 나는 수를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"여덜","mis":"K2-1-u4-X01"},{"t":"여덥","mis":"K2-1-u4-X06"}],"explanation":["일곱 다음의 수는 「여덟」이라고 써요.","「여덜」은 소리 나는 대로 썼어요.","「여덥」은 받침 글자를 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#2','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',2,'mc','auto','받침이 [ㄱ] 소리로 나는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":2,"kind":"mc","stem":"받침이 [ㄱ] 소리로 나는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"닭 · 흙 · 읽다","correct":true},{"t":"닭 · 넓다 · 읽다","mis":"K2-1-u4-X03"},{"t":"값 · 앉다 · 흙","mis":"K2-1-u4-X03"}],"explanation":["ㄺ 받침인 「닭」·「흙」·「읽다」는 [ㄱ] 소리가 나요.","「넓다」는 [ㄹ], 「값」은 [ㅂ], 「앉다」는 [ㄴ] 소리가 나요.","받침 짝마다 나는 소리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#3','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','「젊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X04']::text[],false,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"「젊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[점따]","correct":true},{"t":"[절따]","mis":"K2-1-u4-X03"},{"t":"[점다]","mis":"K2-1-u4-X04"}],"explanation":["ㄻ 받침은 [ㅁ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[절따]는 다른 쪽 글자 소리로 읽었어요.","[점다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#4','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"은솔 — 「앉다 → [안다]」","correct":true,"mis_target":"K2-1-u4-X04"},{"t":"태민 — 「많다 → [만타]」","mis":"K2-1-u4-X17"},{"t":"아린 — 「맑다 → [막따]」","mis":"K2-1-u4-X17"}],"explanation":["「앉다」는 [안따]라고 읽어요.","뒤의 「다」가 [따]로 세게 소리 나요.","태민이와 아린이는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#5','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',3,'mc','auto','받아쓰기에서 바르게 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":5,"concept":"K2-1-u4-C3","difficulty":3,"kind":"mc","stem":"받아쓰기에서 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「닭이 모이를 먹는다.」","correct":true},{"t":"「닥이 모이를 먹는다.」","mis":"K2-1-u4-X01"},{"t":"「닯이 모이를 먹는다.」","mis":"K2-1-u4-X06"}],"explanation":["「닭」은 받침 ㄹ과 ㄱ을 모두 써요.","「닥」은 소리 나는 대로 썼어요.","「닯」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#6','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',3,'ox','auto','[안따]로 소리 나는 「앉다」와 [안타]로 소리 나는 「않다」는 받침 글자가 서로 달라요.',ARRAY['K2-1-u4-X06']::text[],false,'{"seq":6,"concept":"K2-1-u4-C3","difficulty":3,"kind":"ox","stem":"[안따]로 소리 나는 「앉다」와 [안타]로 소리 나는 「않다」는 받침 글자가 서로 달라요.","answer":"O","reason_options":[{"t":"「앉다」는 ㄵ, 「않다」는 ㄶ 받침이니까","correct":true},{"t":"소리가 비슷하면 글자도 같으니까","mis":"K2-1-u4-X06"}],"mis":"K2-1-u4-X06","explanation":["「앉다」는 ㄵ, 「않다」는 ㄶ 받침이에요.","소리가 비슷해도 받침 짝이 다르면 뜻이 다른 말이에요.","뜻을 떠올리며 받침을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#7','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','받침이 나머지와 다른 소리로 나는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X03']::text[],false,'{"seq":7,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"받침이 나머지와 다른 소리로 나는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"넓다","mis":"K2-1-u4-X03"},{"t":"짧다","mis":"K2-1-u4-X03"}],"explanation":["「값」의 ㅄ은 [ㅂ] 소리가 나요.","「넓다」·「짧다」의 ㄼ은 둘 다 [ㄹ] 소리가 나요.","받침 짝마다 나는 소리를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#8','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',4,'mc','auto','[흑]·[닥]·[갑]처럼 들리는 낱말을 쓸 때 기억할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":8,"concept":"K2-1-u4-C3","difficulty":4,"kind":"mc","stem":"[흑]·[닥]·[갑]처럼 들리는 낱말을 쓸 때 기억할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"소리는 하나여도 받침 두 글자를 모두 살려 써요","correct":true},{"t":"들리는 소리 그대로 받침을 하나만 써요","mis":"K2-1-u4-X01"},{"t":"받침 두 글자를 아무것이나 골라 써요","mis":"K2-1-u4-X06"}],"explanation":["「흙」·「닭」·「값」처럼 받침 두 글자를 모두 써요.","소리대로 받침을 하나만 쓰면 틀려요.","받침 짝은 낱말마다 정해져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#9','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C3',4,'essay','teacher','받아쓰기 공책에 「값」을 「갑」이라고 쓴 친구가 있어요. 바르게 쓰는 방법과 그렇게 써야 하는 까닭을 친구에게 알려 주는 말로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C3","difficulty":4,"kind":"essay","stem":"받아쓰기 공책에 「값」을 「갑」이라고 쓴 친구가 있어요. 바르게 쓰는 방법과 그렇게 써야 하는 까닭을 친구에게 알려 주는 말로 써 보세요.","answer_guide":{"answer":"예: 「값」은 [갑]으로 소리 나지만 받침 ㅂ과 ㅅ을 모두 살려 「값」이라고 써야 해. 겹받침은 읽을 때 한 소리만 나도 쓸 때는 두 글자를 다 쓰거든.","scoring_points":["「값」으로 바르게 고쳐 썼는가","받침 두 글자(ㅂ·ㅅ)를 모두 살려 써야 함을 썼는가","읽는 소리와 쓰는 글자가 다를 수 있다는 까닭을 썼는가"]},"explanation":["바르게 고치기.","받침 두 글자.","소리와 글자의 차이."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L03_challenge#10','kor',2,1,'u4','L03','g2_1_kor_u4_L03_challenge','lesson_challenge','K2-1-u4-C2',4,'essay','teacher','「닭」, 「앉다」, 「넓다」를 바르게 읽는 소리를 쓰고, 겹받침 낱말을 바르게 읽는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C2","difficulty":4,"kind":"essay","stem":"「닭」, 「앉다」, 「넓다」를 바르게 읽는 소리를 쓰고, 겹받침 낱말을 바르게 읽는 방법을 써 보세요.","answer_guide":{"answer":"예: [닥], [안따], [널따]. 겹받침은 받침 두 글자 가운데 한 글자의 소리로 읽어요.","scoring_points":["세 낱말의 소리를 바르게 썼는가","뒤 글자가 세게 나는 소리([따])까지 살렸는가","겹받침은 한 글자 소리로 읽는다는 방법을 썼는가"]},"explanation":["바른 소리 셋.","뒤 글자 소리.","읽는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#1','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',1,'mc','auto','글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],true,'{"seq":1,"concept":"K2-1-u4-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?","options":[{"t":"흙","correct":true},{"t":"닭","mis":"K2-1-u4-X07"},{"t":"바구니","mis":"K2-1-u4-X07"}],"explanation":["「할머니와 텃밭에 가서 흙을 골랐어요.」라고 했어요.","닭은 흙을 밟고 지나갔고, 바구니에는 채소를 담았어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 토요일에 언니와 간 곳은 어디인가요?","options":[{"t":"도서관","correct":true},{"t":"시장","mis":"K2-1-u4-X07"},{"t":"텃밭","mis":"K2-1-u4-X07"}],"explanation":["「토요일에 언니와 도서관에 갔어요.」라고 했어요.","시장이나 텃밭은 글에 나오지 않아요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#2','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',1,'mc','auto','글을 읽고 답해 보세요. 글에 나온 낱말 가운데 겹받침이 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":2,"concept":"K2-1-u4-C4","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 낱말 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"하늘이","mis":"K2-1-u4-X05"},{"t":"상추","mis":"K2-1-u4-X05"}],"explanation":["「닭」은 받침 자리에 ㄹ과 ㄱ이 있어요.","「하늘이」의 「늘」은 받침이 하나, 「상추」의 「상」도 받침이 하나예요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 글에 나온 낱말 가운데 겹받침이 있는 낱말은 어느 것인가요?","options":[{"t":"읽었어요","correct":true},{"t":"언니와","mis":"K2-1-u4-X05"},{"t":"그림책을","mis":"K2-1-u4-X05"}],"explanation":["「읽었어요」의 「읽」은 받침이 ㄺ이에요.","「언니와」·「그림책을」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#3','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C2',1,'mc','auto','글을 읽고 답해 보세요. 글에 나온 「흙」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],true,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 「흙」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[흑]","correct":true},{"t":"[흘]","mis":"K2-1-u4-X03"},{"t":"[흘ㄱ]","mis":"K2-1-u4-X02"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나서 [흑]이에요.","[흘]은 다른 쪽 글자 소리로 읽었어요.","두 글자를 모두 소리 내지 않아요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 글에 나온 「값」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[갑]","correct":true},{"t":"[갓]","mis":"K2-1-u4-X03"},{"t":"[갑ㅅ]","mis":"K2-1-u4-X02"}],"explanation":["ㅄ 받침은 [ㅂ] 소리가 나서 [갑]이에요.","[갓]은 다른 쪽 글자 소리로 읽었어요.","두 글자를 모두 소리 내지 않아요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#4','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',1,'ox','auto','글을 읽고 답해 보세요. 상추 잎은 넓고 고추는 짧아요.',ARRAY['K2-1-u4-X07']::text[],true,'{"seq":4,"concept":"K2-1-u4-C4","difficulty":1,"kind":"ox","stem":"글을 읽고 답해 보세요. 상추 잎은 넓고 고추는 짧아요.","answer":"O","reason_options":[{"t":"글에 그렇게 쓰여 있으니까","correct":true},{"t":"고추가 상추보다 크니까","mis":"K2-1-u4-X07"}],"mis":"K2-1-u4-X07","explanation":["「상추 잎은 넓고 고추는 짧아요.」라고 했어요.","글에 쓰인 내용으로 답해요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 도서관에서 책을 한 권만 빌렸어요.","answer":"X","reason_options":[{"t":"읽고 싶은 책이 많아서 두 권을 빌렸다고 했으니까","correct":true},{"t":"도서관에서는 한 권만 빌릴 수 있으니까","mis":"K2-1-u4-X07"}],"explanation":["「두 권을 빌렸어요.」라고 했어요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#5','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C2',2,'match','auto','글에 나온 낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"글에 나온 낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"흙","r":"[흑]"},{"l":"밟고","r":"[밥꼬]"},{"l":"닭","r":"[닥]"}],"mis":"K2-1-u4-X03","explanation":["「흙」은 [흑]이라고 읽어요.","「밟고」는 [밥꼬]라고 읽어요.","「닭」은 [닥]이라고 읽어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글에 나온 낱말의 기본 모양과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"값","r":"[갑]"},{"l":"많다","r":"[만타]"},{"l":"없다","r":"[업따]"}],"explanation":["「값」은 [갑]이라고 읽어요.","「많다」는 [만타]라고 읽어요.","「없다」는 [업따]라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#6','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],true,'{"seq":6,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"맑은 · 닭 · 넓고","correct":true},{"t":"하늘이 · 닭 · 넓고","mis":"K2-1-u4-X05"},{"t":"텃밭에 · 상추 · 고추는","mis":"K2-1-u4-X05"}],"explanation":["「맑은」·「닭」·「넓고」는 모두 겹받침이 있어요.","「하늘이」·「텃밭에」·「상추」·「고추는」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"앉아 · 읽고 · 많아서","correct":true},{"t":"언니와 · 읽고 · 많아서","mis":"K2-1-u4-X05"},{"t":"의자에 · 바닷가는 · 두","mis":"K2-1-u4-X05"}],"explanation":["「앉아」·「읽고」·「많아서」는 모두 겹받침이 있어요.","「언니와」·「의자에」·「바닷가는」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#7','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 바구니가 묵직했던 까닭은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],true,'{"seq":7,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 바구니가 묵직했던 까닭은 무엇인가요?","options":[{"t":"채소가 많아서","correct":true},{"t":"닭이 들어가서","mis":"K2-1-u4-X07"},{"t":"흙을 가득 담아서","mis":"K2-1-u4-X07"}],"explanation":["「바구니에 채소가 많아서 묵직했어요.」라고 했어요.","닭이나 흙을 담았다는 말은 글에 없어요.","글에 쓰인 까닭을 찾아요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 떡이 하나도 남지 않은 까닭은 무엇인가요?","options":[{"t":"동생과 나누어 먹어서","correct":true},{"t":"값이 비싸서","mis":"K2-1-u4-X07"},{"t":"떡집에 사람이 많아서","mis":"K2-1-u4-X07"}],"explanation":["「동생과 나누어 먹으니 남은 떡이 없었어요.」라고 했어요.","다른 까닭은 글에 없어요.","글에 쓰인 까닭을 찾아요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#8','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'sa','auto','글을 읽고 답해 보세요. 흙을 밟고 지나간 동물의 이름을 글에서 찾아 바르게 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u4-C4","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 흙을 밟고 지나간 동물의 이름을 글에서 찾아 바르게 써 보세요.","answer":["닭"],"explanation":["「닭 한 마리가 흙을 밟고 지나갔어요.」라고 했어요.","[닥]으로 읽지만 「닭」이라고 써요.","받침 ㄹ과 ㄱ을 모두 써요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 엄마가 물어보신 것은 꿀떡의 무엇인가요? 글에서 찾아 바르게 써 보세요.","answer":["값"],"explanation":["「엄마가 꿀떡 값을 물어보셨어요.」라고 했어요.","[갑]으로 읽지만 「값」이라고 써요.","받침 ㅂ과 ㅅ을 모두 써요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#9','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',2,'mc','auto','글을 읽다가 겹받침 낱말이 나오면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X07','K2-1-u4-X02']::text[],true,'{"seq":9,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽다가 겹받침 낱말이 나오면 어떻게 읽으면 좋을까요?","options":[{"t":"잠깐 멈추고 바른 소리를 떠올려 읽어요","correct":true},{"t":"겹받침 낱말은 건너뛰고 읽어요","mis":"K2-1-u4-X07"},{"t":"받침 두 글자를 모두 소리 내어 읽어요","mis":"K2-1-u4-X02"}],"explanation":["겹받침 낱말에서 잠깐 멈추면 바른 소리로 읽을 수 있어요.","건너뛰면 글의 뜻을 놓쳐요.","두 글자를 다 소리 내면 틀려요."],"variant_rule":{"alt":[{"stem":"글 속 겹받침 낱말을 바르게 읽으면서 함께 생각할 것은 무엇인가요?","options":[{"t":"글이 무슨 내용인지","correct":true},{"t":"글에 글자가 몇 개인지","mis":"K2-1-u4-X07"},{"t":"받침 글자 모양이 예쁜지","mis":"K2-1-u4-X07"}],"explanation":["바르게 읽으면서 글의 내용도 함께 떠올려요.","글자 수나 글자 모양은 글의 내용이 아니에요.","그래야 글을 잘 읽은 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_basic#10','kor',2,1,'u4','L06','g2_1_kor_u4_L06_basic','lesson_basic','K2-1-u4-C4',3,'error','auto','글을 읽고 겹받침 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K2-1-u4-X05','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 겹받침 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"현우 — 「텃밭에」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"지안 — 「밟고」","mis":"K2-1-u4-X17"},{"t":"도담 — 「많아서」","mis":"K2-1-u4-X17"}],"explanation":["「텃」과 「밭」은 받침이 하나씩뿐이라 겹받침이 아니에요.","「밟고」·「많아서」는 겹받침 낱말이에요.","지안이와 도담이는 바르게 찾았어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글을 읽고 겹받침 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"예린 — 「바닷가는」","correct":true,"mis_target":"K2-1-u4-X05"},{"t":"하준 — 「앉아」","mis":"K2-1-u4-X17"},{"t":"서아 — 「넓었어요」","mis":"K2-1-u4-X17"}],"explanation":["「바닷가는」에는 겹받침이 없어요.","「앉아」·「넓었어요」는 겹받침 낱말이에요.","하준이와 서아는 바르게 찾았어요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#1','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말을 모두 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말을 모두 모은 것은 어느 것인가요?","options":[{"t":"많았어요 · 값 · 없었어요","correct":true},{"t":"많았어요 · 값 · 떡집","mis":"K2-1-u4-X05"},{"t":"시장에 · 값 · 없었어요","mis":"K2-1-u4-X05"}],"explanation":["「많았어요」·「값」·「없었어요」에 겹받침이 있어요.","「떡집」·「시장에」에는 겹받침이 없어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#2','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 「나」는 도서관에서 어디에 앉았나요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":2,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「나」는 도서관에서 어디에 앉았나요?","options":[{"t":"창가 의자","correct":true},{"t":"바닷가 모래밭","mis":"K2-1-u4-X07"},{"t":"언니 옆 바닥","mis":"K2-1-u4-X07"}],"explanation":["「창가 의자에 앉아 그림책을 읽었어요.」라고 했어요.","바닷가 모래밭은 책 속 장면이에요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#3','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C2',3,'mc','auto','글을 읽고 답해 보세요. 글에 나온 「맑은」의 기본 모양 「맑다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X04']::text[],false,'{"seq":3,"concept":"K2-1-u4-C2","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 「맑은」의 기본 모양 「맑다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[막따]","correct":true},{"t":"[말따]","mis":"K2-1-u4-X03"},{"t":"[막다]","mis":"K2-1-u4-X04"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나고, 뒤의 「다」는 [따]로 소리 나요.","[말따]는 다른 쪽 글자 소리로 읽었어요.","[막다]는 뒤 글자 소리가 바뀌는 것을 놓쳤어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#4','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C2',3,'error','auto','글에 나온 낱말의 기본 모양을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"글에 나온 낱말의 기본 모양을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"민호 — 「값 → [갓]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"하린 — 「없다 → [업따]」","mis":"K2-1-u4-X17"},{"t":"지후 — 「많다 → [만타]」","mis":"K2-1-u4-X17"}],"explanation":["「값」은 [갑]이라고 읽어요.","ㅄ 받침은 [ㅂ] 소리가 나요.","하린이와 지후는 바르게 읽었어요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#5','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',3,'ox','auto','글을 읽고 답해 보세요. 책 속 바닷가는 모래밭이 짧았어요.',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":5,"concept":"K2-1-u4-C4","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 책 속 바닷가는 모래밭이 짧았어요.","answer":"X","reason_options":[{"t":"글에 모래밭이 넓었다고 했으니까","correct":true},{"t":"바닷가 모래밭은 원래 짧으니까","mis":"K2-1-u4-X07"}],"mis":"K2-1-u4-X07","explanation":["「책 속 바닷가는 모래밭이 넓었어요.」라고 했어요.","글에 없는 내용으로 답하면 안 돼요.","글에서 찾아 확인해요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#6','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',3,'mc','auto','글을 읽고 답해 보세요. 이 글을 소리 내어 읽을 때 잠깐 멈추어 바른 소리를 떠올려야 할 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":6,"concept":"K2-1-u4-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 이 글을 소리 내어 읽을 때 잠깐 멈추어 바른 소리를 떠올려야 할 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"흙 · 닭 · 밟고","correct":true},{"t":"할머니 · 텃밭 · 바구니","mis":"K2-1-u4-X05"},{"t":"상추 · 고추 · 채소","mis":"K2-1-u4-X05"}],"explanation":["「흙」·「닭」·「밟고」는 겹받침 낱말이에요.","다른 낱말에는 겹받침이 없어요.","겹받침 낱말에서 멈추어 바르게 읽어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#7','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',3,'mc','auto','글을 읽고 답해 보세요. 글쓴이의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":7,"concept":"K2-1-u4-C4","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 글쓴이의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 싶은 책이 많아 신나는 마음","correct":true},{"t":"책이 없어서 속상한 마음","mis":"K2-1-u4-X07"},{"t":"바닷가에 못 가서 서운한 마음","mis":"K2-1-u4-X07"}],"explanation":["읽고 싶은 책이 많아서 두 권을 빌렸다고 했어요.","책이 없거나 바닷가에 못 갔다는 말은 글에 없어요.","글의 내용에서 마음을 짐작해요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#8','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',4,'mc','auto','글 속 겹받침 낱말을 바르게 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X12','K2-1-u4-X07']::text[],false,'{"seq":8,"concept":"K2-1-u4-C4","difficulty":4,"kind":"mc","stem":"글 속 겹받침 낱말을 바르게 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"낱말의 뜻이 바르게 전해져 글 내용을 잘 알 수 있어요","correct":true},{"t":"글을 더 빨리 끝낼 수 있어요","mis":"K2-1-u4-X12"},{"t":"겹받침 낱말을 건너뛰어도 돼요","mis":"K2-1-u4-X07"}],"explanation":["바르게 읽어야 듣는 사람도 뜻을 바르게 알아들어요.","빨리 읽는 것이 목적이 아니에요.","겹받침 낱말을 건너뛰면 내용을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#9','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',4,'essay','teacher','「할머니의 텃밭」에서 겹받침 낱말을 세 개 찾아 쓰고, 그 가운데 하나를 바르게 읽는 소리를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C4","difficulty":4,"kind":"essay","stem":"「할머니의 텃밭」에서 겹받침 낱말을 세 개 찾아 쓰고, 그 가운데 하나를 바르게 읽는 소리를 써 보세요.","answer_guide":{"answer":"예: 닭, 흙, 넓고 — 「닭」은 [닥]이라고 읽어요.","scoring_points":["글에 나온 겹받침 낱말을 세 개 찾았는가","겹받침이 없는 낱말을 섞지 않았는가","고른 낱말의 바른 소리를 썼는가"]},"explanation":["겹받침 낱말 셋.","섞지 않기.","바른 소리."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L06_challenge#10','kor',2,1,'u4','L06','g2_1_kor_u4_L06_challenge','lesson_challenge','K2-1-u4-C4',4,'essay','teacher','닭·흙·앉다·많다 가운데 두 개 이상을 넣어 내가 겪은 일을 두 문장으로 쓰고, 넣은 겹받침 낱말에 밑줄을 그어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C4","difficulty":4,"kind":"essay","stem":"닭·흙·앉다·많다 가운데 두 개 이상을 넣어 내가 겪은 일을 두 문장으로 쓰고, 넣은 겹받침 낱말에 밑줄을 그어 보세요.","answer_guide":{"answer":"예: 할머니 댁 마당에서 닭이 흙을 파고 있었다. 나는 마루에 앉아 한참 동안 구경했다.","scoring_points":["겹받침 낱말을 두 개 이상 넣었는가","겹받침 낱말을 받침 두 글자를 살려 바르게 썼는가","겪은 일이 드러나게 두 문장으로 썼는가"]},"explanation":["겹받침 낱말 두 개 이상.","바르게 쓰기.","두 문장."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#1','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],true,'{"seq":1,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"슬픈","mis":"K2-1-u4-X09"},{"t":"무서운","mis":"K2-1-u4-X09"}],"explanation":["「통통」·「콩콩」·「와아」가 신나는 기분을 줘요.","슬프거나 무서운 말은 시에 없어요.","시에 나오는 말에서 분위기를 느껴요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"조용한","correct":true},{"t":"시끄러운","mis":"K2-1-u4-X09"},{"t":"화난","mis":"K2-1-u4-X09"}],"explanation":["「살며시」·「쉿」·「새근새근」이 조용한 기분을 줘요.","시끄럽거나 화난 말은 시에 없어요.","시에 나오는 말에서 분위기를 느껴요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#2','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','신나는 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],true,'{"seq":2,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"신나는 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"콩콩","correct":true},{"t":"살며시","mis":"K2-1-u4-X10"},{"t":"가만히","mis":"K2-1-u4-X10"}],"explanation":["「콩콩」은 힘차게 뛰는 신나는 느낌을 줘요.","「살며시」·「가만히」는 조용한 느낌을 줘요.","소리 내어 따라 하며 느껴 봐요."],"variant_rule":{"alt":[{"stem":"조용한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"살며시","correct":true},{"t":"통통","mis":"K2-1-u4-X10"},{"t":"와아","mis":"K2-1-u4-X10"}],"explanation":["「살며시」는 소리 없이 가만가만 움직이는 느낌을 줘요.","「통통」·「와아」는 신나는 느낌을 줘요.","소리 내어 따라 하며 느껴 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#3','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'ox','auto','시를 읽고 답해 보세요. 이 시에서는 포근한 분위기가 느껴져요.',ARRAY['K2-1-u4-X08']::text[],true,'{"seq":3,"concept":"K2-1-u4-C6","difficulty":1,"kind":"ox","stem":"시를 읽고 답해 보세요. 이 시에서는 포근한 분위기가 느껴져요.","answer":"O","reason_options":[{"t":"「따스한 햇살」·「엄마 품」 같은 말이 포근하게 느껴지니까","correct":true},{"t":"시가 짧으면 언제나 포근하니까","mis":"K2-1-u4-X08"}],"mis":"K2-1-u4-X08","explanation":["따스한 햇살과 엄마 품이 포근한 기분을 줘요.","시의 길이로 분위기가 정해지지 않아요.","시의 말과 장면을 살펴요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시에서는 시끌벅적하고 신나는 분위기가 느껴져요.","answer":"X","reason_options":[{"t":"「살며시」·「쉿」·「새근새근」이 조용한 느낌을 주니까","correct":true},{"t":"달이 나오는 시는 모두 신나니까","mis":"K2-1-u4-X09"}],"explanation":["이 시는 조용한 분위기예요.","달이 나온다고 분위기가 정해지지 않아요.","시에 나오는 말을 살펴요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#4','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',1,'mc','auto','시의 분위기를 찾을 때 살펴보면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u4-X08']::text[],true,'{"seq":4,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시의 분위기를 찾을 때 살펴보면 좋은 것은 어느 것인가요?","options":[{"t":"시에 나오는 말과 장면","correct":true},{"t":"시의 글자 수","mis":"K2-1-u4-X08"},{"t":"시를 쓴 종이의 색깔","mis":"K2-1-u4-X08"}],"explanation":["시에 나오는 말과 장면이 기분을 만들어요.","글자 수나 종이 색깔은 분위기와 상관없어요.","소리 내어 읽으며 장면을 떠올려요."],"variant_rule":{"alt":[{"stem":"시의 분위기를 느끼는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"소리 내어 읽으며 장면을 떠올려요","correct":true},{"t":"글자 수를 세어 봐요","mis":"K2-1-u4-X08"},{"t":"제목만 읽고 넘어가요","mis":"K2-1-u4-X09"}],"explanation":["소리 내어 읽고 장면을 떠올리면 기분이 느껴져요.","글자 수를 세는 것은 분위기와 상관없어요.","제목만 읽으면 시의 말과 장면을 놓쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#5','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'match','auto','시의 장면과 어울리는 분위기를 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":2,"kind":"match","stem":"시의 장면과 어울리는 분위기를 이어 보세요.","pairs":[{"l":"콩콩 뛰는 운동장","r":"신나는"},{"l":"소복소복 눈 오는 밤","r":"조용한"},{"l":"따스한 봄 햇살","r":"포근한"}],"mis":"K2-1-u4-X09","explanation":["콩콩 뛰는 운동장은 신나는 분위기예요.","소복소복 눈 오는 밤은 조용한 분위기예요.","따스한 봄 햇살은 포근한 분위기예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시의 장면과 어울리는 분위기를 이어 보세요.","pairs":[{"l":"하나 둘 발맞추는 아이들","r":"씩씩한"},{"l":"톡톡 춤추는 빗방울","r":"신나는"},{"l":"새근새근 잠든 아기","r":"조용한"}],"explanation":["하나 둘 발맞추는 아이들은 씩씩한 분위기예요.","톡톡 춤추는 빗방울은 신나는 분위기예요.","새근새근 잠든 아기는 조용한 분위기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#6','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기가 조용하게 느껴지는 까닭은 무엇인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X08']::text[],true,'{"seq":6,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기가 조용하게 느껴지는 까닭은 무엇인가요?","options":[{"t":"「소리 없이」·「잠들어요」 같은 말이 고요한 장면을 보여 주니까","correct":true},{"t":"눈이 나오는 시는 언제나 조용하니까","mis":"K2-1-u4-X09"},{"t":"시가 네 줄이니까","mis":"K2-1-u4-X08"}],"explanation":["시의 말이 고요한 장면을 그려 줘요.","눈이 나와도 「펑펑, 눈싸움하자」처럼 신날 수 있어요.","줄 수는 분위기와 상관없어요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시의 분위기가 신나게 느껴지는 까닭은 무엇인가요?","options":[{"t":"「통통」·「콩콩」·「와아」 같은 말이 뛰노는 장면을 보여 주니까","correct":true},{"t":"공은 언제나 신나는 물건이니까","mis":"K2-1-u4-X09"},{"t":"시가 네 줄이니까","mis":"K2-1-u4-X08"}],"explanation":["시의 말이 신나게 뛰노는 장면을 그려 줘요.","공이 나와도 시의 말에 따라 분위기는 달라져요.","줄 수는 분위기와 상관없어요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#7','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'blank','auto','신나는 분위기가 나도록 빈칸에 들어갈 말로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#8','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'mc','auto','같은 시를 읽고 느낀 분위기를 친구에게 말할 때 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X08']::text[],true,'{"seq":8,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"같은 시를 읽고 느낀 분위기를 친구에게 말할 때 알맞은 것은 어느 것인가요?","options":[{"t":"느낀 분위기와 그렇게 느낀 까닭을 함께 말해요","correct":true},{"t":"까닭 없이 「그냥」이라고만 말해요","mis":"K2-1-u4-X09"},{"t":"시에 나온 사람 이름을 말해요","mis":"K2-1-u4-X08"}],"explanation":["시의 말이나 장면을 까닭으로 들어 말해요.","까닭이 있어야 친구도 고개를 끄덕여요.","사람 이름은 분위기가 아니에요."],"variant_rule":{"alt":[{"stem":"친구가 「달밤」을 읽고 「포근한 분위기야」라고 말했어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"까닭을 들어 보면 그렇게 느낄 수도 있어요","correct":true},{"t":"시의 분위기는 꼭 하나라서 틀렸어요","mis":"K2-1-u4-X09"},{"t":"분위기는 아무렇게나 말해도 돼요","mis":"K2-1-u4-X09"}],"explanation":["느낀 분위기는 친구마다 조금 다를 수 있어요.","시의 말과 장면으로 까닭을 말하면 돼요.","아무렇게나가 아니라 까닭이 있어야 해요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#9','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',2,'sa','auto','시를 읽고 답해 보세요. 이 시에서 힘차게 걷는 씩씩한 모습이 느껴지는 말을 하나 찾아 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u4-C6","difficulty":2,"kind":"sa","stem":"시를 읽고 답해 보세요. 이 시에서 힘차게 걷는 씩씩한 모습이 느껴지는 말을 하나 찾아 써 보세요.","answer":["힘차게","발맞춰","씩씩해요","가슴 펴고","하나 둘"],"explanation":["「힘차게」·「발맞춰」·「씩씩해요」 같은 말이 씩씩한 기분을 줘요.","시에 나오는 말에서 찾아요.","찾은 말을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"},"variant_rule":{"alt":[{"stem":"시를 읽고 답해 보세요. 이 시에서 빗방울이 신나게 노는 모습이 느껴지는 말을 하나 찾아 써 보세요.","answer":["톡톡","첨벙첨벙","랄랄라","춤을 춰요","노래해요"],"explanation":["「톡톡」·「첨벙첨벙」·「랄랄라」 같은 말이 신나는 기분을 줘요.","시에 나오는 말에서 찾아요.","찾은 말을 소리 내어 읽어 봐요."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_basic#10','kor',2,1,'u4','L08','g2_1_kor_u4_L08_basic','lesson_basic','K2-1-u4-C6',3,'error','auto','시를 읽고 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시를 읽고 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"시우 — 「와글와글 시끄러운 분위기야.」","correct":true,"mis_target":"K2-1-u4-X09"},{"t":"다은 — 「고요하고 조용한 분위기야.」","mis":"K2-1-u4-X17"},{"t":"로아 — 「하얗고 차분한 분위기야.」","mis":"K2-1-u4-X17"}],"explanation":["「소리 없이」·「잠들어요」는 조용한 느낌이에요.","시끄러운 말은 시에 없어요.","다은이와 로아는 알맞게 말했어요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 분위기를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"준우 — 「쓸쓸하고 슬픈 분위기야.」","correct":true,"mis_target":"K2-1-u4-X09"},{"t":"하린 — 「밝고 신나는 분위기야.」","mis":"K2-1-u4-X17"},{"t":"지안 — 「즐겁고 들뜬 분위기야.」","mis":"K2-1-u4-X17"}],"explanation":["「통통」·「콩콩」·「와아」는 신나는 느낌이에요.","슬픈 말은 시에 없어요.","하린이와 지안이는 알맞게 말했어요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#1','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',2,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X09']::text[],false,'{"seq":1,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"조용한","mis":"K2-1-u4-X10"},{"t":"무서운","mis":"K2-1-u4-X09"}],"explanation":["「톡톡」·「첨벙첨벙」·「랄랄라」가 신나는 기분을 줘요.","조용하거나 무서운 장면은 없어요.","시의 말과 장면을 살펴요."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#2','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',2,'mc','auto','조용한 분위기가 느껴지는 말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":2,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"조용한 분위기가 느껴지는 말만 모은 것은 어느 것인가요?","options":[{"t":"살며시 · 가만히 · 소복소복","correct":true},{"t":"살며시 · 콩콩 · 소복소복","mis":"K2-1-u4-X10"},{"t":"와아 · 통통 · 들썩들썩","mis":"K2-1-u4-X10"}],"explanation":["「살며시」·「가만히」·「소복소복」은 조용한 느낌을 줘요.","「콩콩」·「와아」·「통통」·「들썩들썩」은 신나는 느낌이에요.","따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#3','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'mc','auto','두 시를 읽고 분위기를 바르게 짝지은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#4','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"은솔 — 「쉿, 새근새근 잠든 아기 → 신나는」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"태민 — 「와아 와아 들썩이는 운동장 → 신나는」","mis":"K2-1-u4-X17"},{"t":"아린 — 「하나 둘 발맞추는 아이들 → 씩씩한」","mis":"K2-1-u4-X17"}],"explanation":["「쉿」·「새근새근」은 조용한 느낌이에요.","잠든 아기 장면은 조용한 분위기와 어울려요.","태민이와 아린이는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#5','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'ox','auto','시를 읽고 답해 보세요. 이 시의 「쉿」을 「야호」로 바꾸면 시의 분위기도 달라져요.',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":3,"kind":"ox","stem":"시를 읽고 답해 보세요. 이 시의 「쉿」을 「야호」로 바꾸면 시의 분위기도 달라져요.","answer":"O","reason_options":[{"t":"시에 나오는 말에 따라 느껴지는 기분이 달라지니까","correct":true},{"t":"낱말 하나로는 분위기가 바뀌지 않으니까","mis":"K2-1-u4-X09"}],"mis":"K2-1-u4-X09","explanation":["「야호」는 신나는 느낌이라 조용한 분위기가 흔들려요.","낱말 하나도 분위기를 바꿀 수 있어요.","그래서 시의 말을 잘 살펴요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#6','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',3,'mc','auto','시를 읽고 답해 보세요. 이 시에서 포근한 느낌을 가장 잘 주는 장면은 어느 것인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":6,"concept":"K2-1-u4-C6","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시에서 포근한 느낌을 가장 잘 주는 장면은 어느 것인가요?","options":[{"t":"햇살이 꽃잎을 살살 쓰다듬는 장면","correct":true},{"t":"공이 통통 튀는 장면","mis":"K2-1-u4-X07"},{"t":"친구들이 와아 소리치는 장면","mis":"K2-1-u4-X07"}],"explanation":["햇살이 꽃잎을 살살 쓰다듬는 장면이 포근해요.","공이 튀거나 소리치는 장면은 이 시에 없어요.","시에 있는 장면에서 찾아요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#7','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C5',3,'mc','auto','분위기에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u4-X09','K2-1-u4-X08']::text[],false,'{"seq":7,"concept":"K2-1-u4-C5","difficulty":3,"kind":"mc","stem":"분위기에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"「같은 눈 내리는 장면도 쓴 말에 따라 신나게도, 조용하게도 느껴질 수 있어.」","correct":true},{"t":"「눈이 나오는 시는 언제나 조용한 분위기야.」","mis":"K2-1-u4-X09"},{"t":"「분위기는 시의 제목 글자 수로 정해져.」","mis":"K2-1-u4-X08"}],"explanation":["어떤 말을 썼는지에 따라 분위기가 달라져요.","소재 하나로 분위기가 정해지지 않아요.","글자 수는 분위기와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#8','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',4,'mc','auto','시를 읽고 답해 보세요. 이 시를 신나는 분위기로 바꾸려고 해요. 바꾼 줄로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":8,"concept":"K2-1-u4-C6","difficulty":4,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 신나는 분위기로 바꾸려고 해요. 바꾼 줄로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「펑펑 눈이 와요 / 와아, 눈싸움하자」","correct":true},{"t":"「소복소복 눈이 / 소리 없이 내려요」","mis":"K2-1-u4-X10"},{"t":"「쉿, 눈이 / 살며시 잠들어요」","mis":"K2-1-u4-X10"}],"explanation":["「펑펑」·「와아」·「눈싸움」이 신나는 기분을 줘요.","다른 두 줄은 여전히 조용한 느낌이에요.","바꿀 말을 고를 때 분위기를 먼저 정해요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#9','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',4,'essay','teacher','「공놀이」의 분위기를 쓰고, 그렇게 느낀 까닭을 시에 나오는 말을 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C6","difficulty":4,"kind":"essay","stem":"「공놀이」의 분위기를 쓰고, 그렇게 느낀 까닭을 시에 나오는 말을 들어 써 보세요.","answer_guide":{"answer":"예: 신나는 분위기예요. 「통통」·「콩콩」·「와아 와아」 같은 말에서 친구들이 신나게 뛰노는 모습이 떠오르기 때문이에요.","scoring_points":["분위기를 알맞게 썼는가","시에 나오는 말을 까닭으로 들었는가","그 말에서 떠오른 장면이나 기분을 썼는가"]},"explanation":["분위기.","시의 말.","장면·기분."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L08_challenge#10','kor',2,1,'u4','L08','g2_1_kor_u4_L08_challenge','lesson_challenge','K2-1-u4-C6',4,'essay','teacher','조용한 분위기가 느껴지는 짧은 시를 두 줄로 지어 보고, 어떤 말 때문에 조용하게 느껴지는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C6","difficulty":4,"kind":"essay","stem":"조용한 분위기가 느껴지는 짧은 시를 두 줄로 지어 보고, 어떤 말 때문에 조용하게 느껴지는지 써 보세요.","answer_guide":{"answer":"예: 「가만가만 고양이가 / 햇볕에 졸고 있어요」 — 「가만가만」·「졸고」 때문에 조용하게 느껴져요.","scoring_points":["두 줄로 시를 지었는가","조용한 느낌을 주는 말을 넣었는가","조용하게 느껴지는 까닭을 시의 말로 썼는가"]},"explanation":["두 줄 시.","조용한 말.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#1','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',1,'mc','auto','시를 읽고 답해 보세요. 이 시는 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X11']::text[],true,'{"seq":1,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시는 어떻게 읽으면 좋을까요?","options":[{"t":"밝고 빠르게","correct":true},{"t":"작고 느릿느릿하게","mis":"K2-1-u4-X11"},{"t":"화내며 세게","mis":"K2-1-u4-X11"}],"explanation":["신나는 시는 밝고 빠르게 읽으면 분위기가 살아나요.","작고 느리게 읽으면 신나는 느낌이 사라져요.","화내며 읽는 것은 이 시와 어울리지 않아요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시는 어떻게 읽으면 좋을까요?","options":[{"t":"천천히 부드럽게","correct":true},{"t":"빠르고 크게","mis":"K2-1-u4-X11"},{"t":"화내며 세게","mis":"K2-1-u4-X11"}],"explanation":["조용한 시는 천천히 부드럽게 읽으면 분위기가 살아나요.","빠르고 크게 읽으면 조용한 느낌이 사라져요.","화내며 읽는 것은 이 시와 어울리지 않아요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#2','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',1,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],true,'{"seq":2,"concept":"K2-1-u4-C8","difficulty":1,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「달님이 / 살며시 // 창문을 / 들여다봐요」","correct":true},{"t":"「달 / 님이 / 살 / 며시 창문을 들여다봐요」","mis":"K2-1-u4-X13"},{"t":"「달님이살며시창문을들여다봐요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","한 글자씩 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「강아지가 / 꼬리를 // 흔들어요」","correct":true},{"t":"「강 / 아지가꼬 / 리를 흔들어요」","mis":"K2-1-u4-X13"},{"t":"「강아지가꼬리를흔들어요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#3','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',1,'ox','auto','「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.',ARRAY['K2-1-u4-X14']::text[],true,'{"seq":3,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.","answer":"O","reason_options":[{"t":"「//」는 조금 더 쉬라는 표시이니까","correct":true},{"t":"「//」는 쉬지 말고 붙여 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「/」에서는 조금 쉬고, 「//」에서는 조금 더 쉬어요.","쉬는 길이를 표시로 알려 줘요.","표시를 따라 읽으면 뜻이 잘 드러나요."],"variant_rule":{"alt":[{"stem":"「/」 표시에서는 쉬지 않고 붙여 읽어요.","answer":"X","reason_options":[{"t":"「/」는 조금 쉬어 읽으라는 표시이니까","correct":true},{"t":"「/」는 빠르게 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"explanation":["「/」에서는 조금 쉬어 읽어요.","「//」에서는 조금 더 쉬어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#4','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',1,'mc','auto','모든 시를 한 가지 목소리로 똑같이 읽으면 어떻게 될까요?',ARRAY['K2-1-u4-X11']::text[],true,'{"seq":4,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"모든 시를 한 가지 목소리로 똑같이 읽으면 어떻게 될까요?","options":[{"t":"시마다 다른 분위기가 잘 살아나지 않아요","correct":true},{"t":"모든 시가 더 신나게 느껴져요","mis":"K2-1-u4-X11"},{"t":"시의 뜻이 저절로 잘 드러나요","mis":"K2-1-u4-X11"}],"explanation":["시마다 분위기가 달라서 읽는 목소리도 달라야 해요.","같은 목소리로 읽으면 분위기가 비슷해져요.","분위기에 맞게 목소리를 바꾸어요."],"variant_rule":{"alt":[{"stem":"시를 소리 내어 읽기 전에 분위기에 맞게 정해야 할 것은 어느 것인가요?","options":[{"t":"목소리 크기와 빠르기","correct":true},{"t":"시의 제목 글자","mis":"K2-1-u4-X08"},{"t":"읽을 종이의 크기","mis":"K2-1-u4-X08"}],"explanation":["분위기에 맞게 목소리 크기와 빠르기를 정해요.","제목 글자나 종이 크기는 읽는 방법이 아니에요.","그러면 시의 분위기가 살아나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#5','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'match','auto','분위기와 어울리는 읽는 방법을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C7","difficulty":2,"kind":"match","stem":"분위기와 어울리는 읽는 방법을 이어 보세요.","pairs":[{"l":"신나는","r":"밝고 빠르게"},{"l":"조용한","r":"천천히 부드럽게"},{"l":"씩씩한","r":"또렷하고 힘차게"}],"mis":"K2-1-u4-X11","explanation":["신나는 시는 밝고 빠르게 읽어요.","조용한 시는 천천히 부드럽게 읽어요.","씩씩한 시는 또렷하고 힘차게 읽어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 분위기와 어울리는 읽는 방법을 이어 보세요.","pairs":[{"l":"포근한","r":"다정하고 따뜻하게"},{"l":"신나는","r":"밝고 빠르게"},{"l":"조용한","r":"작고 천천히"}],"explanation":["포근한 시는 다정하고 따뜻하게 읽어요.","신나는 시는 밝고 빠르게 읽어요.","조용한 시는 작고 천천히 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#6','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기를 살려 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],true,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기를 살려 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"또렷하고 힘차게","correct":true},{"t":"졸린 듯 작게","mis":"K2-1-u4-X11"},{"t":"울먹이며 느리게","mis":"K2-1-u4-X11"}],"explanation":["씩씩한 시는 또렷하고 힘차게 읽어요.","졸리거나 울먹이는 목소리는 씩씩한 느낌과 맞지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시를 읽고 답해 보세요. 이 시의 분위기를 살려 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"다정하고 따뜻하게","correct":true},{"t":"크게 소리 지르며","mis":"K2-1-u4-X11"},{"t":"빠르고 거칠게","mis":"K2-1-u4-X11"}],"explanation":["포근한 시는 다정하고 따뜻하게 읽어요.","소리 지르거나 거칠게 읽으면 포근한 느낌이 사라져요.","분위기를 먼저 떠올리고 목소리를 정해요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#7','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',2,'mc','auto','「쉿, 아기가 새근새근 자요」를 알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],true,'{"seq":7,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"「쉿, 아기가 새근새근 자요」를 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「쉿, // 아기가 / 새근새근 자요」","correct":true},{"t":"「쉿아 / 기가새 / 근새근 자요」","mis":"K2-1-u4-X13"},{"t":"「쉿, 아 / 기가 / 새근 / 새근자요」","mis":"K2-1-u4-X13"}],"explanation":["「쉿,」 뒤에서 조금 더 쉬고, 뜻 덩어리로 묶어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","뜻이 이어지는 말끼리 묶어 읽어요."],"variant_rule":{"alt":[{"stem":"「우리는 씩씩한 어린이」를 알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「우리는 / 씩씩한 어린이」","correct":true},{"t":"「우 / 리는씩 / 씩한 어린이」","mis":"K2-1-u4-X13"},{"t":"「우리는씩씩한어린이」","mis":"K2-1-u4-X13"}],"explanation":["「우리는」과 「씩씩한 어린이」를 한 덩어리씩 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#8','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'ox','auto','시는 빠르게 읽을수록 언제나 잘 읽은 거예요.',ARRAY['K2-1-u4-X12']::text[],true,'{"seq":8,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"시는 빠르게 읽을수록 언제나 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"분위기에 맞는 빠르기로 읽어야 하니까","correct":true},{"t":"빨리 읽으면 무조건 잘 읽은 것이니까","mis":"K2-1-u4-X12"}],"mis":"K2-1-u4-X12","explanation":["조용한 시는 천천히 읽어야 분위기가 살아나요.","빠르기도 분위기에 맞추어요.","빨리 읽는 것과 잘 읽는 것은 달라요."],"variant_rule":{"alt":[{"stem":"조용한 시는 천천히, 신나는 시는 조금 빠르게 읽으면 분위기가 살아나요.","answer":"O","reason_options":[{"t":"분위기에 따라 알맞은 빠르기가 다르니까","correct":true},{"t":"모든 시는 같은 빠르기로 읽어야 하니까","mis":"K2-1-u4-X11"}],"explanation":["분위기에 따라 빠르기를 바꾸어 읽어요.","같은 빠르기로 읽으면 분위기가 살지 않아요.","시에 맞는 빠르기를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#9','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C7',2,'blank','auto','「살며시 눈이 내려요」처럼 조용한 시를 읽을 때는 목소리를 (     ) 해요.',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],true,'{"seq":9,"concept":"K2-1-u4-C7","difficulty":2,"kind":"blank","stem":"「살며시 눈이 내려요」처럼 조용한 시를 읽을 때는 목소리를 (     ) 해요.","options":[{"t":"부드럽고 작게","correct":true},{"t":"크고 거칠게","mis":"K2-1-u4-X11"},{"t":"빠르고 세게","mis":"K2-1-u4-X12"}],"explanation":["조용한 시는 부드럽고 작은 목소리가 어울려요.","크고 거친 목소리는 조용한 느낌을 깨요.","빠르고 세게 읽으면 고요함이 사라져요."],"variant_rule":{"alt":[{"stem":"「와아 와아 운동장이」처럼 신나는 시를 읽을 때는 목소리를 (     ) 해요.","options":[{"t":"밝고 힘 있게","correct":true},{"t":"작고 졸리게","mis":"K2-1-u4-X11"},{"t":"울먹이듯 느리게","mis":"K2-1-u4-X11"}],"explanation":["신나는 시는 밝고 힘 있는 목소리가 어울려요.","작고 졸린 목소리는 신나는 느낌을 지워요.","울먹이는 목소리는 슬픈 느낌을 줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_basic#10','kor',2,1,'u4','L10','g2_1_kor_u4_L10_basic','lesson_basic','K2-1-u4-C8',3,'error','auto','「달님이 살며시 창가에 앉아요」를 띄어 읽었어요. 알맞지 않게 띄어 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X13','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C8","difficulty":3,"kind":"error","stem":"「달님이 살며시 창가에 앉아요」를 띄어 읽었어요. 알맞지 않게 띄어 읽은 친구는 누구인가요?","options":[{"t":"지호 — 「달 / 님이살 / 며시 창가에 앉아요」","correct":true,"mis_target":"K2-1-u4-X13"},{"t":"예린 — 「달님이 / 살며시 // 창가에 / 앉아요」","mis":"K2-1-u4-X17"},{"t":"소율 — 「달님이 살며시 / 창가에 앉아요」","mis":"K2-1-u4-X17"}],"explanation":["지호는 낱말 가운데에서 끊어 읽어 뜻이 드러나지 않아요.","예린이와 소율이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳은 조금 달라도 뜻이 드러나면 괜찮아요."],"variant_rule":{"alt":[{"stem":"「작은 새가 나뭇가지에 앉아 노래해요」를 띄어 읽었어요. 알맞지 않게 띄어 읽은 친구는 누구인가요?","options":[{"t":"민지 — 「작 / 은새가 / 나뭇가 / 지에 앉아 노래해요」","correct":true,"mis_target":"K2-1-u4-X13"},{"t":"하늘 — 「작은 새가 / 나뭇가지에 앉아 // 노래해요」","mis":"K2-1-u4-X17"},{"t":"도윤 — 「작은 새가 / 나뭇가지에 / 앉아 노래해요」","mis":"K2-1-u4-X17"}],"explanation":["민지는 낱말 가운데에서 끊어 읽어 뜻이 드러나지 않아요.","하늘이와 도윤이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳은 조금 달라도 뜻이 드러나면 괜찮아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#1','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',2,'mc','auto','시를 읽고 답해 보세요. 친구가 이 시를 크고 빠르게 읽었어요. 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X12','K2-1-u4-X11']::text[],false,'{"seq":1,"concept":"K2-1-u4-C7","difficulty":2,"kind":"mc","stem":"시를 읽고 답해 보세요. 친구가 이 시를 크고 빠르게 읽었어요. 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「조용한 시니까 천천히 부드럽게 읽어 보자.」","correct":true},{"t":"「더 크고 더 빠르게 읽으면 좋겠어.」","mis":"K2-1-u4-X12"},{"t":"「소리치며 읽으면 더 잘 들려.」","mis":"K2-1-u4-X11"}],"explanation":["「달밤」은 조용한 시예요.","크고 빠르게 읽으면 조용한 분위기가 사라져요.","분위기에 맞는 목소리를 알려 줘요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#2','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽으면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u4-X13','K2-1-u4-X12']::text[],false,'{"seq":2,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽으면 좋은 점은 어느 것인가요?","options":[{"t":"뜻이 잘 드러나고 듣는 사람이 알아듣기 쉬워요","correct":true},{"t":"글자를 하나씩 끊어 읽을 수 있어요","mis":"K2-1-u4-X13"},{"t":"쉬는 곳 없이 빨리 읽을 수 있어요","mis":"K2-1-u4-X12"}],"explanation":["뜻 덩어리로 띄어 읽으면 뜻이 잘 전해져요.","한 글자씩 끊는 것은 알맞게 띄어 읽기가 아니에요.","쉬지 않고 빨리 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#3','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',3,'mc','auto','「와아, 눈이 온다」를 두 가지 방법으로 읽었어요. 신나는 분위기가 더 잘 살아나는 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X13']::text[],false,'{"seq":3,"concept":"K2-1-u4-C7","difficulty":3,"kind":"mc","stem":"「와아, 눈이 온다」를 두 가지 방법으로 읽었어요. 신나는 분위기가 더 잘 살아나는 방법은 어느 것인가요?","options":[{"t":"밝고 들뜬 목소리로 조금 빠르게 읽기","correct":true},{"t":"작고 낮은 목소리로 아주 느리게 읽기","mis":"K2-1-u4-X11"},{"t":"한 글자씩 뚝뚝 끊어 읽기","mis":"K2-1-u4-X13"}],"explanation":["밝고 들뜬 목소리가 「와아」의 신나는 느낌을 살려요.","작고 느리게 읽으면 신나는 느낌이 사라져요.","한 글자씩 끊으면 뜻도 분위기도 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#4','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',3,'error','auto','시를 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X17']::text[],false,'{"seq":4,"concept":"K2-1-u4-C7","difficulty":3,"kind":"error","stem":"시를 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도담 — 「봄볕 시는 크게 소리 지르며 읽을래.」","correct":true,"mis_target":"K2-1-u4-X11"},{"t":"현우 — 「공놀이 시는 밝고 빠르게 읽을래.」","mis":"K2-1-u4-X17"},{"t":"하준 — 「발맞춰 걸어요 시는 또렷하고 힘차게 읽을래.」","mis":"K2-1-u4-X17"}],"explanation":["「봄볕」은 포근한 시라 다정하고 따뜻하게 읽어요.","소리 지르면 포근한 느낌이 사라져요.","현우와 하준이는 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#5','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',3,'ox','auto','「아기가 / 새근새근 // 자요」는 「새근새근」 뒤에서 가장 길게 쉬어요.',ARRAY['K2-1-u4-X14']::text[],false,'{"seq":5,"concept":"K2-1-u4-C8","difficulty":3,"kind":"ox","stem":"「아기가 / 새근새근 // 자요」는 「새근새근」 뒤에서 가장 길게 쉬어요.","answer":"O","reason_options":[{"t":"「//」 표시가 있어 조금 더 쉬니까","correct":true},{"t":"「/」에서 더 길게 쉬니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「//」가 있는 곳에서 조금 더 쉬어요.","「/」에서는 조금만 쉬어요.","표시를 따라 쉬는 길이를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#6','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',3,'mc','auto','뜻이 바르게 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":6,"concept":"K2-1-u4-C8","difficulty":3,"kind":"mc","stem":"뜻이 바르게 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「아버지가 / 방에 들어가신다」","correct":true},{"t":"「아버지가방에 / 들어가신다」","mis":"K2-1-u4-X13"},{"t":"「아 / 버지가 / 방에들 / 어가신다」","mis":"K2-1-u4-X13"}],"explanation":["「아버지가」와 「방에 들어가신다」로 묶어야 뜻이 바르게 드러나요.","「아버지가방에」로 붙이면 「가방에」로 잘못 들릴 수 있어요.","띄어 읽는 곳에 따라 뜻이 달라질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#7','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',3,'mc','auto','시를 읽고 답해 보세요. 이 시를 분위기를 살려 읽을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":7,"concept":"K2-1-u4-C7","difficulty":3,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시를 분위기를 살려 읽을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"천천히, 부드럽고 차분한 목소리로","correct":true},{"t":"빠르고 큰 목소리로","mis":"K2-1-u4-X11"},{"t":"화난 목소리로 세게","mis":"K2-1-u4-X11"}],"explanation":["「첫눈」은 조용한 분위기의 시예요.","빠르고 크게 읽으면 조용한 느낌이 사라져요.","화난 목소리는 이 시와 어울리지 않아요."],"asset":{"type":"passage","lines":["소복소복 눈이","소리 없이 내려요","온 마을이","하얗게 잠들어요"],"title":"첫눈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#8','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',4,'mc','auto','「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],false,'{"seq":8,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?","options":[{"t":"앞줄은 밝고 빠르게, 뒷줄은 작고 천천히 바꾸어 읽어요","correct":true},{"t":"처음 목소리 그대로 끝까지 읽어요","mis":"K2-1-u4-X11"},{"t":"두 줄 모두 크고 빠르게 읽어요","mis":"K2-1-u4-X12"}],"explanation":["분위기가 바뀌는 곳에서 목소리도 바꾸어요.","한 가지 목소리로 읽으면 바뀐 분위기가 드러나지 않아요.","「쉿」부터는 작고 천천히 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#9','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C7',4,'essay','teacher','「비 오는 날」을 어떤 목소리와 빠르기로 읽으면 좋을지 쓰고, 그렇게 정한 까닭을 시의 말을 들어 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C7","difficulty":4,"kind":"essay","stem":"「비 오는 날」을 어떤 목소리와 빠르기로 읽으면 좋을지 쓰고, 그렇게 정한 까닭을 시의 말을 들어 써 보세요.","answer_guide":{"answer":"예: 밝은 목소리로 조금 빠르게 읽을래요. 「톡톡」·「첨벙첨벙」·「랄랄라」가 신나는 느낌을 주기 때문이에요.","scoring_points":["목소리를 정해 썼는가","빠르기를 정해 썼는가","시의 말을 들어 까닭을 썼는가"]},"explanation":["목소리.","빠르기.","시의 말로 까닭."],"asset":{"type":"passage","lines":["톡톡 빗방울이","우산 위에서 춤을 춰요","첨벙첨벙 웅덩이","랄랄라 노래해요"],"title":"비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L10_challenge#10','kor',2,1,'u4','L10','g2_1_kor_u4_L10_challenge','lesson_challenge','K2-1-u4-C8',4,'essay','teacher','「작은 다람쥐가 도토리를 들고 나무 위로 올라가요」에 「/」와 「//」를 넣어 알맞게 띄어 읽기 표시를 하고, 그렇게 띄어 읽은 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C8","difficulty":4,"kind":"essay","stem":"「작은 다람쥐가 도토리를 들고 나무 위로 올라가요」에 「/」와 「//」를 넣어 알맞게 띄어 읽기 표시를 하고, 그렇게 띄어 읽은 까닭을 써 보세요.","answer_guide":{"answer":"예: 작은 다람쥐가 / 도토리를 들고 // 나무 위로 / 올라가요. — 뜻이 이어지는 말끼리 묶어 읽으면 뜻이 잘 드러나기 때문이에요.","scoring_points":["「/」와 「//」를 모두 넣었는가","낱말 가운데를 끊지 않고 뜻 덩어리로 묶었는가","뜻이 잘 드러난다는 까닭을 썼는가"]},"explanation":["표시 두 가지.","뜻 덩어리.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#1','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',1,'mc','auto','시를 낭송할 때 알맞은 태도는 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],true,'{"seq":1,"concept":"K2-1-u4-C9","difficulty":1,"kind":"mc","stem":"시를 낭송할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"분위기를 살려 또박또박 읽어요","correct":true},{"t":"장난치며 아무렇게나 읽어요","mis":"K2-1-u4-X15"},{"t":"작게 우물우물 읽어요","mis":"K2-1-u4-X15"}],"explanation":["분위기를 살려 또박또박 읽어야 시가 잘 전해져요.","장난치며 읽으면 시의 기분이 흐려져요.","작게 우물우물 읽으면 친구들이 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"친구들 앞에서 시를 낭송할 때 목소리로 알맞은 것은 어느 것인가요?","options":[{"t":"모두가 잘 들리게 또렷하게","correct":true},{"t":"나만 들리게 작게","mis":"K2-1-u4-X15"},{"t":"웃음을 참지 못하고 킥킥거리며","mis":"K2-1-u4-X15"}],"explanation":["친구들이 모두 들을 수 있게 또렷하게 낭송해요.","작게 읽으면 들리지 않아요.","킥킥거리면 시의 분위기가 흐려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#2','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',1,'mc','auto','친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],true,'{"seq":2,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?","options":[{"t":"조용히 끝까지 들어요","correct":true},{"t":"옆 친구와 떠들어요","mis":"K2-1-u4-X16"},{"t":"다른 책을 읽어요","mis":"K2-1-u4-X16"}],"explanation":["조용히 끝까지 들어 주면 친구가 마음껏 낭송할 수 있어요.","떠들거나 딴짓하면 친구의 시를 놓쳐요.","내가 낭송할 때를 떠올려 봐요."],"variant_rule":{"alt":[{"stem":"친구의 낭송이 끝났을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"박수를 쳐 주어요","correct":true},{"t":"고개를 돌리고 하품해요","mis":"K2-1-u4-X16"},{"t":"「틀렸다」고 놀려요","mis":"K2-1-u4-X16"}],"explanation":["박수는 잘 들었다는 마음을 전해요.","하품하거나 놀리면 친구가 속상해요.","내가 낭송할 때를 떠올려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#3','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',1,'mc','auto','낭송할 시를 고를 때 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],true,'{"seq":3,"concept":"K2-1-u4-C9","difficulty":1,"kind":"mc","stem":"낭송할 시를 고를 때 알맞은 것은 어느 것인가요?","options":[{"t":"읽었을 때 마음에 들고 분위기가 좋은 시","correct":true},{"t":"무조건 가장 긴 시","mis":"K2-1-u4-X15"},{"t":"읽어 보지 않고 아무거나 고른 시","mis":"K2-1-u4-X15"}],"explanation":["마음에 드는 시를 골라야 분위기를 살려 낭송할 수 있어요.","길이로 고르는 것이 아니에요.","먼저 읽어 보고 골라요."],"variant_rule":{"alt":[{"stem":"「시로 여는 우리 반」에서 맨 처음 할 일은 어느 것인가요?","options":[{"t":"마음에 드는 시 고르기","correct":true},{"t":"친구들 앞에서 낭송하기","mis":"K2-1-u4-X15"},{"t":"친구에게 박수 쳐 주기","mis":"K2-1-u4-X15"}],"explanation":["먼저 시를 골라야 연습하고 낭송할 수 있어요.","낭송은 연습을 한 뒤에 해요.","박수는 친구의 낭송이 끝난 뒤에 쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#4','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',1,'ox','auto','친구가 낭송하는 도중에 「나도 할래!」 하고 끼어들어도 돼요.',ARRAY['K2-1-u4-X16']::text[],true,'{"seq":4,"concept":"K2-1-u4-C10","difficulty":1,"kind":"ox","stem":"친구가 낭송하는 도중에 「나도 할래!」 하고 끼어들어도 돼요.","answer":"X","reason_options":[{"t":"친구가 끝까지 낭송할 수 있게 기다려야 하니까","correct":true},{"t":"하고 싶은 말은 바로 해야 하니까","mis":"K2-1-u4-X16"}],"mis":"K2-1-u4-X16","explanation":["친구의 낭송이 끝날 때까지 기다려요.","끼어들면 친구가 시를 끝까지 들려줄 수 없어요.","내 차례를 기다리는 것도 좋은 태도예요."],"variant_rule":{"alt":[{"stem":"친구가 낭송하는 시를 잘 들으면 친구의 마음을 더 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"친구가 고른 시에 친구의 마음이 담겨 있으니까","correct":true},{"t":"듣는 것은 낭송과 아무 상관이 없으니까","mis":"K2-1-u4-X16"}],"explanation":["친구가 고른 시에는 친구의 마음이 담겨 있어요.","잘 들어야 그 마음이 전해져요.","시를 나누면 서로를 더 잘 알게 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#5','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',2,'match','auto','낭송 차례와 할 일을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u4-C9","difficulty":2,"kind":"match","stem":"낭송 차례와 할 일을 알맞게 이어 보세요.","pairs":[{"l":"시 고르기","r":"마음에 드는 시 찾기"},{"l":"연습하기","r":"분위기 살려 읽어 보기"},{"l":"낭송하기","r":"친구들 앞에서 또렷하게 발표하기"}],"mis":"K2-1-u4-X15","explanation":["시 고르기는 마음에 드는 시를 찾는 일이에요.","연습하기는 분위기를 살려 읽어 보는 일이에요.","낭송하기는 친구들 앞에서 또렷하게 발표하는 일이에요."],"variant_rule":{"alt":[{"stem":"낭송 차례를 알맞게 이어 보세요.","pairs":[{"l":"첫째","r":"시 고르기"},{"l":"둘째","r":"분위기 살려 연습하기"},{"l":"셋째","r":"친구들 앞에서 낭송하기"}],"explanation":["첫째로 마음에 드는 시를 골라요.","둘째로 분위기를 살려 연습해요.","셋째로 친구들 앞에서 낭송해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#6','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',2,'mc','auto','시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],true,'{"seq":6,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 고르기 → 연습하기 → 낭송하기","correct":true},{"t":"낭송하기 → 시 고르기 → 연습하기","mis":"K2-1-u4-X15"},{"t":"연습하기 → 낭송하기 → 시 고르기","mis":"K2-1-u4-X15"}],"explanation":["시를 고르고, 연습한 뒤에, 낭송해요.","시를 고르기 전에 낭송할 수는 없어요.","연습 없이 낭송하면 분위기를 살리기 어려워요."],"variant_rule":{"alt":[{"stem":"연습을 하지 않고 바로 낭송하면 어떻게 될까요?","options":[{"t":"분위기를 살려 또박또박 읽기 어려워요","correct":true},{"t":"언제나 더 멋지게 낭송할 수 있어요","mis":"K2-1-u4-X15"},{"t":"시의 분위기가 저절로 살아나요","mis":"K2-1-u4-X15"}],"explanation":["연습을 해야 분위기에 맞는 목소리를 찾을 수 있어요.","연습 없이 바로 하면 더듬거리기 쉬워요.","분위기는 저절로 살아나지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#7','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',2,'mc','auto','시를 친구들과 나누면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],true,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":2,"kind":"mc","stem":"시를 친구들과 나누면 좋은 점은 어느 것인가요?","options":[{"t":"여러 가지 분위기의 시를 만날 수 있어요","correct":true},{"t":"낭송하는 친구만 즐거워요","mis":"K2-1-u4-X16"},{"t":"듣는 친구는 할 일이 없어요","mis":"K2-1-u4-X16"}],"explanation":["친구마다 고른 시가 달라 여러 분위기를 느낄 수 있어요.","듣는 친구도 함께 즐거워요.","잘 들어 주는 것이 듣는 친구가 할 일이에요."],"variant_rule":{"alt":[{"stem":"시를 나누면 우리 반이 어떻게 될까요?","options":[{"t":"서로의 마음을 알게 되어 따뜻해져요","correct":true},{"t":"서로 시끄럽게 떠들게 돼요","mis":"K2-1-u4-X16"},{"t":"친구의 시는 들을 필요가 없어져요","mis":"K2-1-u4-X16"}],"explanation":["시를 나누면 친구의 마음을 알게 돼요.","떠드는 것은 좋은 듣기 태도가 아니에요.","친구의 시도 잘 들어야 나눌 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#8','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C9',2,'blank','auto','낭송할 때는 시를 무조건 외우기보다 (     ) 낭송해요.',ARRAY['K2-1-u4-X12','K2-1-u4-X15']::text[],true,'{"seq":8,"concept":"K2-1-u4-C9","difficulty":2,"kind":"blank","stem":"낭송할 때는 시를 무조건 외우기보다 (     ) 낭송해요.","options":[{"t":"분위기를 느끼며","correct":true},{"t":"아무렇게나 빠르게","mis":"K2-1-u4-X12"},{"t":"작게 중얼거리며","mis":"K2-1-u4-X15"}],"explanation":["분위기를 느끼며 읽어야 듣는 사람에게 잘 전해져요.","빠르게만 읽으면 분위기가 살지 않아요.","작게 중얼거리면 들리지 않아요."],"variant_rule":{"alt":[{"stem":"낭송을 연습할 때는 고른 시의 (     )를 살펴 읽는 방법을 정해요.","options":[{"t":"분위기","correct":true},{"t":"글자 수","mis":"K2-1-u4-X08"},{"t":"쪽수","mis":"K2-1-u4-X08"}],"explanation":["시의 분위기를 살펴 목소리와 빠르기를 정해요.","글자 수나 쪽수는 읽는 방법을 정해 주지 않아요.","분위기에 맞게 연습해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#9','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',2,'sa','auto','친구의 낭송이 끝나면 두 손뼉을 마주쳐 소리를 내어 칭찬해요. 이것을 무엇이라고 하나요? 두 글자로 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"K2-1-u4-C10","difficulty":2,"kind":"sa","stem":"친구의 낭송이 끝나면 두 손뼉을 마주쳐 소리를 내어 칭찬해요. 이것을 무엇이라고 하나요? 두 글자로 써 보세요.","answer":["박수"],"explanation":["잘 들었다는 마음을 박수로 전해요.","박수를 받으면 낭송한 친구도 기뻐요.","듣는 사람이 할 수 있는 좋은 반응이에요."],"variant_rule":{"alt":[{"stem":"친구가 낭송할 때는 떠들지 않고 (     ) 들어요. 빈칸에 알맞은 말을 써 보세요.","answer":["조용히","가만히","귀 기울여"],"explanation":["조용히 들어야 친구의 시가 잘 들려요.","떠들면 친구도 다른 친구들도 시를 놓쳐요.","끝까지 조용히 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_basic#10','kor',2,1,'u4','L12','g2_1_kor_u4_L12_basic','lesson_basic','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],true,'{"seq":10,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"시우 — 「몰래 짝에게 쪽지를 썼어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"다은 — 「낭송하는 친구를 바라보며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"로아 — 「끝난 뒤 박수를 쳤어요.」","mis":"K2-1-u4-X17"}],"explanation":["낭송할 때 쪽지를 쓰는 것은 딴짓이에요.","친구를 바라보며 듣고 박수를 쳐 주는 것은 좋은 태도예요.","다은이와 로아는 알맞게 행동했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"준우 — 「낭송 도중에 크게 하품하며 엎드렸어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"지안 — 「시의 장면을 떠올리며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"하린 — 「끝까지 조용히 들었어요.」","mis":"K2-1-u4-X17"}],"explanation":["크게 하품하며 엎드리면 낭송하는 친구가 속상해요.","장면을 떠올리며 끝까지 조용히 듣는 것은 좋은 태도예요.","지안이와 하린이는 알맞게 행동했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#1','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',2,'mc','auto','포근한 분위기의 시를 낭송하려고 해요. 연습할 때 알맞은 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X15']::text[],false,'{"seq":1,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"포근한 분위기의 시를 낭송하려고 해요. 연습할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"다정하고 따뜻한 목소리로 읽어 봐요","correct":true},{"t":"크게 소리 지르며 읽어 봐요","mis":"K2-1-u4-X11"},{"t":"연습 없이 바로 낭송해요","mis":"K2-1-u4-X15"}],"explanation":["포근한 시는 다정하고 따뜻한 목소리가 어울려요.","소리 지르면 포근한 느낌이 사라져요.","연습해야 분위기를 살릴 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#2','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',2,'mc','auto','친구의 낭송을 듣고 해 주는 칭찬으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":2,"concept":"K2-1-u4-C10","difficulty":2,"kind":"mc","stem":"친구의 낭송을 듣고 해 주는 칭찬으로 알맞은 것은 어느 것인가요?","options":[{"t":"「조용한 시를 부드럽게 읽어서 달밤이 떠올랐어.」","correct":true},{"t":"「너무 길어서 지루했어.」","mis":"K2-1-u4-X16"},{"t":"「나는 안 들었어.」","mis":"K2-1-u4-X16"}],"explanation":["어떤 점이 좋았는지 구체적으로 말해 주면 좋아요.","지루했다는 말은 친구를 속상하게 해요.","듣지 않았다면 칭찬할 수도 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#3','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'error','auto','시 낭송을 준비했어요. 알맞지 않게 준비한 친구는 누구인가요?',ARRAY['K2-1-u4-X15','K2-1-u4-X17']::text[],false,'{"seq":3,"concept":"K2-1-u4-C9","difficulty":3,"kind":"error","stem":"시 낭송을 준비했어요. 알맞지 않게 준비한 친구는 누구인가요?","options":[{"t":"은솔 — 「시를 고르자마자 연습 없이 낭송했어요.」","correct":true,"mis_target":"K2-1-u4-X15"},{"t":"태민 — 「시의 분위기를 살펴 읽는 방법을 정했어요.」","mis":"K2-1-u4-X17"},{"t":"아린 — 「여러 번 소리 내어 연습했어요.」","mis":"K2-1-u4-X17"}],"explanation":["연습 없이 낭송하면 분위기를 살리기 어려워요.","분위기를 살피고 여러 번 연습하는 것이 알맞은 준비예요.","태민이와 아린이는 알맞게 준비했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#4','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'mc','auto','낭송하는 친구가 지켜야 할 것만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":4,"concept":"K2-1-u4-C9","difficulty":3,"kind":"mc","stem":"낭송하는 친구가 지켜야 할 것만 모은 것은 어느 것인가요?","options":[{"t":"또렷하게 · 분위기를 살려 · 듣는 친구를 바라보며","correct":true},{"t":"작게 · 우물우물 · 바닥만 보며","mis":"K2-1-u4-X15"},{"t":"장난스럽게 · 아무렇게나 · 빠르게만","mis":"K2-1-u4-X15"}],"explanation":["또렷하게, 분위기를 살려, 친구를 바라보며 낭송해요.","작게 우물우물 읽으면 들리지 않아요.","장난스럽게 빠르게만 읽으면 분위기가 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#5','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'ox','auto','낭송은 시를 외우기만 하면 분위기를 느끼지 않아도 잘한 거예요.',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":5,"concept":"K2-1-u4-C9","difficulty":3,"kind":"ox","stem":"낭송은 시를 외우기만 하면 분위기를 느끼지 않아도 잘한 거예요.","answer":"X","reason_options":[{"t":"분위기를 느끼며 살려 읽어야 듣는 사람에게 잘 전해지니까","correct":true},{"t":"외우기만 하면 낭송은 끝이니까","mis":"K2-1-u4-X15"}],"mis":"K2-1-u4-X15","explanation":["외우는 것보다 분위기를 느끼며 읽는 것이 중요해요.","분위기가 살아야 듣는 사람도 시를 느껴요.","외우지 못해도 시를 보며 낭송할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#6','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',3,'mc','auto','친구의 낭송을 들을 때 함께 하면 좋은 것은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":6,"concept":"K2-1-u4-C10","difficulty":3,"kind":"mc","stem":"친구의 낭송을 들을 때 함께 하면 좋은 것은 어느 것인가요?","options":[{"t":"시의 장면과 분위기를 떠올리며 들어요","correct":true},{"t":"내 차례에 읽을 시만 계속 연습해요","mis":"K2-1-u4-X16"},{"t":"친구 목소리를 흉내 내며 놀려요","mis":"K2-1-u4-X16"}],"explanation":["장면과 분위기를 떠올리며 들으면 시를 함께 느낄 수 있어요.","내 시만 연습하면 친구의 시를 놓쳐요.","흉내 내며 놀리면 친구가 속상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#7','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',3,'mc','auto','하람이가 「공놀이」를 낭송하려고 해요. 가장 알맞은 낭송 계획은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X15']::text[],false,'{"seq":7,"concept":"K2-1-u4-C9","difficulty":3,"kind":"mc","stem":"하람이가 「공놀이」를 낭송하려고 해요. 가장 알맞은 낭송 계획은 어느 것인가요?","options":[{"t":"밝고 신나는 목소리로, 친구들을 보며 또렷하게","correct":true},{"t":"작고 슬픈 목소리로, 고개를 숙이고","mis":"K2-1-u4-X11"},{"t":"장난스럽게 웃으며 아무렇게나","mis":"K2-1-u4-X15"}],"explanation":["「공놀이」는 신나는 시라 밝고 신나는 목소리가 어울려요.","작고 슬픈 목소리는 이 시와 맞지 않아요.","장난스럽게 읽으면 분위기가 흐려져요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#8','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',4,'mc','auto','친구들이 낭송한 시가 서로 달랐어요. 알맞은 생각은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":8,"concept":"K2-1-u4-C10","difficulty":4,"kind":"mc","stem":"친구들이 낭송한 시가 서로 달랐어요. 알맞은 생각은 어느 것인가요?","options":[{"t":"친구마다 마음에 드는 시가 달라 여러 분위기를 느낄 수 있어 좋아요","correct":true},{"t":"모두 같은 시를 낭송해야 해요","mis":"K2-1-u4-X16"},{"t":"내 시와 다른 시는 들을 필요가 없어요","mis":"K2-1-u4-X16"}],"explanation":["서로 다른 시를 나누면 여러 분위기를 만날 수 있어요.","같은 시만 낭송할 필요는 없어요.","다른 시도 잘 들어야 친구의 마음을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#9','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C9',4,'essay','teacher','내가 낭송하고 싶은 시(배운 시나 좋아하는 시)를 하나 정해 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지 계획을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"내가 낭송하고 싶은 시(배운 시나 좋아하는 시)를 하나 정해 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지 계획을 써 보세요.","answer_guide":{"answer":"예: 「첫눈」 — 조용한 분위기예요. 부드럽고 작은 목소리로, 천천히 낭송할 거예요.","scoring_points":["시와 그 분위기를 썼는가","분위기에 맞는 목소리를 정했는가","분위기에 맞는 빠르기를 정했는가"]},"explanation":["시와 분위기.","목소리.","빠르기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_L12_challenge#10','kor',2,1,'u4','L12','g2_1_kor_u4_L12_challenge','lesson_challenge','K2-1-u4-C10',4,'essay','teacher','친구가 시를 낭송할 때 지켜야 할 듣기 태도를 두 가지 쓰고, 그렇게 해야 하는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u4-C10","difficulty":4,"kind":"essay","stem":"친구가 시를 낭송할 때 지켜야 할 듣기 태도를 두 가지 쓰고, 그렇게 해야 하는 까닭을 써 보세요.","answer_guide":{"answer":"예: 조용히 끝까지 들어요. 끝나면 박수를 쳐 줘요. — 친구가 마음 놓고 낭송할 수 있고, 친구 시에 담긴 마음을 잘 알 수 있기 때문이에요.","scoring_points":["좋은 듣기 태도를 두 가지 썼는가","두 가지가 서로 다른 태도인가","그렇게 해야 하는 까닭을 썼는가"]},"explanation":["듣기 태도 둘.","서로 다른 태도.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#1','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"산","mis":"K2-1-u4-X05"},{"t":"손","mis":"K2-1-u4-X05"}],"explanation":["「닭」의 받침 자리에는 ㄹ과 ㄱ, 두 글자가 있어요.","「산」·「손」은 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#2','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C2',1,'mc','auto','「닭」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「닭」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[닥]","correct":true},{"t":"[달]","mis":"K2-1-u4-X03"},{"t":"[달ㄱ]","mis":"K2-1-u4-X02"}],"explanation":["ㄺ 받침은 [ㄱ] 소리가 나서 [닥]이에요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#3','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',1,'mc','auto','[닥]이라고 소리 나는, 「꼬끼오」 하고 우는 동물을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[닥]이라고 소리 나는, 「꼬끼오」 하고 우는 동물을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"닭","correct":true},{"t":"닥","mis":"K2-1-u4-X01"},{"t":"닯","mis":"K2-1-u4-X06"}],"explanation":["[닥]으로 들려도 받침 두 글자를 살려 「닭」이라고 써요.","「닥」은 소리 나는 대로 썼어요.","「닯」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#4','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C5',1,'mc','auto','글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"글이나 시를 읽을 때 느껴지는 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"제목","mis":"K2-1-u4-X08"},{"t":"겹받침","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「제목」·「겹받침」은 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#5','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"신나는","correct":true},{"t":"슬픈","mis":"K2-1-u4-X09"},{"t":"무서운","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 신나는 기분이 느껴져요.","슬픈·무서운 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#6','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C7',1,'mc','auto','신나는 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"신나는 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"밝고 빠르게","correct":true},{"t":"작고 느릿느릿하게","mis":"K2-1-u4-X11"},{"t":"울먹이며 느리게","mis":"K2-1-u4-X11"}],"explanation":["신나는 분위기는 밝고 빠르게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#7','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C10',1,'mc','auto','친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 시를 낭송할 때 좋은 듣기 태도는 어느 것인가요?","options":[{"t":"조용히 끝까지 들어요","correct":true},{"t":"옆 친구와 떠들어요","mis":"K2-1-u4-X16"},{"t":"다른 책을 읽어요","mis":"K2-1-u4-X16"}],"explanation":["조용히 끝까지 들어 주면 친구가 마음껏 낭송할 수 있어요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#8','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C8',1,'ox','auto','「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.',ARRAY['K2-1-u4-X14']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"「//」 표시에서는 「/」 표시보다 조금 더 쉬어 읽어요.","answer":"O","reason_options":[{"t":"「//」는 조금 더 쉬라는 표시이니까","correct":true},{"t":"「//」는 붙여 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「/」에서는 조금 쉬고, 「//」에서는 조금 더 쉬어요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#9','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"닭","r":"[닥]"},{"l":"값","r":"[갑]"},{"l":"흙","r":"[흑]"}],"mis":"K2-1-u4-X03","explanation":["「닭」은 [닥]이라고 읽어요.","「값」은 [갑]이라고 읽어요.","「흙」은 [흑]이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#10','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',2,'ox','auto','「값」은 [갑]으로 소리 나니까 「갑」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「값」은 [갑]으로 소리 나니까 「갑」이라고 써요.","answer":"X","reason_options":[{"t":"소리는 하나여도 받침 두 글자를 살려 쓰니까","correct":true},{"t":"들리는 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「값」은 [갑]으로 읽지만 「값」이라고 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#11','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니와 텃밭에 가서 고른 것은 무엇인가요?","options":[{"t":"흙","correct":true},{"t":"닭","mis":"K2-1-u4-X07"},{"t":"바구니","mis":"K2-1-u4-X07"}],"explanation":["「할머니와 텃밭에 가서 흙을 골랐어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#12','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"맑은 · 닭 · 넓고","correct":true},{"t":"하늘이 · 닭 · 넓고","mis":"K2-1-u4-X05"},{"t":"텃밭에 · 상추 · 고추는","mis":"K2-1-u4-X05"}],"explanation":["「맑은 · 닭 · 넓고」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#13','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C6',2,'mc','auto','신나는 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"신나는 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"콩콩","correct":true},{"t":"살며시","mis":"K2-1-u4-X10"},{"t":"가만히","mis":"K2-1-u4-X10"}],"explanation":["「콩콩」은 신나는 느낌을 줘요.","「살며시」·「가만히」는 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#14','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C7',2,'ox','auto','시는 빠르게 읽을수록 언제나 잘 읽은 거예요.',ARRAY['K2-1-u4-X12']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"시는 빠르게 읽을수록 언제나 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"분위기에 맞는 빠르기로 읽어야 하니까","correct":true},{"t":"빨리 읽으면 무조건 잘 읽은 것이니까","mis":"K2-1-u4-X12"}],"mis":"K2-1-u4-X12","explanation":["조용한 시는 천천히 읽어야 분위기가 살아나요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#15','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C9',2,'mc','auto','시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"시 낭송을 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 고르기 → 연습하기 → 낭송하기","correct":true},{"t":"낭송하기 → 시 고르기 → 연습하기","mis":"K2-1-u4-X15"},{"t":"연습하기 → 낭송하기 → 시 고르기","mis":"K2-1-u4-X15"}],"explanation":["시를 고르고, 연습한 뒤에 낭송해요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#16','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「달님이 / 살며시 // 창문을 / 들여다봐요」","correct":true},{"t":"「달 / 님이 / 살 / 며시 창문을 들여다봐요」","mis":"K2-1-u4-X13"},{"t":"「달님이살며시창문을들여다봐요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#17','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"시우 — 「흙 → [흘]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"다은 — 「닭 → [닥]」","mis":"K2-1-u4-X17"},{"t":"로아 — 「값 → [갑]」","mis":"K2-1-u4-X17"}],"explanation":["「흙」은 [흑]이라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#18','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「흑 위에 꽃씨를 심었다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"다은 — 「연필 값이 비싸다.」","mis":"K2-1-u4-X17"},{"t":"시우 — 「의자에 앉았다.」","mis":"K2-1-u4-X17"}],"explanation":["「흑」은 소리대로 썼어요. 「흙」이라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#19','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「닭이 바구니에 들어갔어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"소율 — 「할머니와 흙을 골랐어.」","mis":"K2-1-u4-X17"},{"t":"지우 — 「상추 잎은 넓었어.」","mis":"K2-1-u4-X17"}],"explanation":["닭은 흙을 밟고 지나갔다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["하늘이 맑은 토요일 아침이에요.","할머니와 텃밭에 가서 흙을 골랐어요.","닭 한 마리가 흙을 밟고 지나갔어요.","상추 잎은 넓고 고추는 짧아요.","바구니에 채소가 많아서 묵직했어요."],"title":"할머니의 텃밭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#20','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"은솔 — 「쉿, 새근새근 잠든 아기 → 신나는」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"태민 — 「와아 와아 들썩이는 운동장 → 신나는」","mis":"K2-1-u4-X17"},{"t":"아린 — 「하나 둘 발맞추는 아이들 → 씩씩한」","mis":"K2-1-u4-X17"}],"explanation":["「쉿」·「새근새근」은 조용한 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#21','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#22','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"시우 — 「몰래 짝에게 쪽지를 썼어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"다은 — 「낭송하는 친구를 바라보며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"로아 — 「끝난 뒤 박수를 쳤어요.」","mis":"K2-1-u4-X17"}],"explanation":["낭송할 때 쪽지를 쓰는 것은 딴짓이에요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#23','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C7',4,'mc','auto','「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「통통 공이 튀어요 / 쉿, 아기가 자요」처럼 한 시 안에서 분위기가 바뀌면 어떻게 읽으면 좋을까요?","options":[{"t":"앞줄은 밝고 빠르게, 뒷줄은 작고 천천히 바꾸어 읽어요","correct":true},{"t":"처음 목소리 그대로 끝까지 읽어요","mis":"K2-1-u4-X11"},{"t":"두 줄 모두 크고 빠르게 읽어요","mis":"K2-1-u4-X12"}],"explanation":["「쉿」부터는 조용한 분위기라 목소리를 바꾸어요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#24','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_a#25','kor',2,1,'u4','','g2_1_kor_u4_review_a','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 신나는 분위기예요. 밝고 빠르게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["통통 공이 튀어요","콩콩 친구도 뛰어요","와아 와아 운동장이","들썩들썩 웃어요"],"title":"공놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#1','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"감","mis":"K2-1-u4-X05"},{"t":"강","mis":"K2-1-u4-X05"}],"explanation":["「값」의 받침 자리에는 ㅂ과 ㅅ, 두 글자가 있어요.","「감」·「강」은 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#2','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C2',1,'mc','auto','「앉다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X03']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「앉다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[안따]","correct":true},{"t":"[안다]","mis":"K2-1-u4-X04"},{"t":"[앚따]","mis":"K2-1-u4-X03"}],"explanation":["ㄵ 받침은 [ㄴ] 소리가 나고 「다」는 [따]로 나서 [안따]예요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#3','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',1,'mc','auto','[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[갑]이라고 소리 나는, 물건을 살 때 치르는 돈을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"값","correct":true},{"t":"갑","mis":"K2-1-u4-X01"},{"t":"갋","mis":"K2-1-u4-X06"}],"explanation":["[갑]으로 들려도 받침 두 글자를 살려 「값」이라고 써요.","「갑」은 소리 나는 대로 썼어요.","「갋」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#4','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C5',1,'mc','auto','「분위기」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"「분위기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"글이나 시를 읽을 때 느껴지는 기분","correct":true},{"t":"글에 나오는 사람의 이름","mis":"K2-1-u4-X08"},{"t":"글에 있는 글자의 수","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「글에 나오는 사람의 이름」·「글에 있는 글자의 수」는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#5','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"조용한","correct":true},{"t":"시끄러운","mis":"K2-1-u4-X09"},{"t":"화난","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 조용한 기분이 느껴져요.","시끄러운·화난 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#6','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C7',1,'mc','auto','조용한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"조용한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"천천히 부드럽게","correct":true},{"t":"빠르고 크게","mis":"K2-1-u4-X11"},{"t":"소리 지르며 세게","mis":"K2-1-u4-X11"}],"explanation":["조용한 분위기는 천천히 부드럽게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#7','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C10',1,'mc','auto','친구의 낭송이 끝났을 때 알맞은 행동은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구의 낭송이 끝났을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"박수를 쳐 주어요","correct":true},{"t":"고개를 돌리고 하품해요","mis":"K2-1-u4-X16"},{"t":"「틀렸다」고 놀려요","mis":"K2-1-u4-X16"}],"explanation":["박수는 잘 들었다는 마음을 전해요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#8','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C8',1,'ox','auto','「/」 표시에서는 쉬지 않고 붙여 읽어요.',ARRAY['K2-1-u4-X14']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"「/」 표시에서는 쉬지 않고 붙여 읽어요.","answer":"X","reason_options":[{"t":"「/」는 조금 쉬어 읽으라는 표시이니까","correct":true},{"t":"「/」는 빠르게 읽으라는 표시이니까","mis":"K2-1-u4-X14"}],"mis":"K2-1-u4-X14","explanation":["「/」에서는 조금 쉬어 읽어요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#9','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"앉다","r":"[안따]"},{"l":"넓다","r":"[널따]"},{"l":"맑다","r":"[막따]"}],"mis":"K2-1-u4-X03","explanation":["「앉다」는 [안따]라고 읽어요.","「넓다」는 [널따]라고 읽어요.","「맑다」는 [막따]라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#10','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',2,'ox','auto','「닭」은 [닥]으로 읽지만 쓸 때는 「닭」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「닭」은 [닥]으로 읽지만 쓸 때는 「닭」이라고 써요.","answer":"O","reason_options":[{"t":"읽는 소리와 쓰는 글자가 다를 수 있으니까","correct":true},{"t":"쓸 때도 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「닭」은 [닥]으로 읽고 「닭」으로 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#11','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 「나」는 도서관 어디에 앉아 책을 읽었나요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「나」는 도서관 어디에 앉아 책을 읽었나요?","options":[{"t":"창가 의자","correct":true},{"t":"바닷가 모래밭","mis":"K2-1-u4-X07"},{"t":"언니 옆 바닥","mis":"K2-1-u4-X07"}],"explanation":["「창가 의자에 앉아 그림책을 읽었어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#12','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"앉아 · 읽고 · 많아서","correct":true},{"t":"언니와 · 읽고 · 많아서","mis":"K2-1-u4-X05"},{"t":"의자에 · 바닷가는 · 두","mis":"K2-1-u4-X05"}],"explanation":["「앉아 · 읽고 · 많아서」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#13','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C6',2,'mc','auto','조용한 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"조용한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"소복소복","correct":true},{"t":"와아","mis":"K2-1-u4-X10"},{"t":"들썩들썩","mis":"K2-1-u4-X10"}],"explanation":["「소복소복」은 조용한 느낌을 줘요.","「와아」·「들썩들썩」은 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#14','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C7',2,'ox','auto','모든 시를 한 가지 목소리로 똑같이 읽어도 분위기가 잘 살아나요.',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"모든 시를 한 가지 목소리로 똑같이 읽어도 분위기가 잘 살아나요.","answer":"X","reason_options":[{"t":"시마다 분위기가 달라 목소리도 바꾸어야 하니까","correct":true},{"t":"목소리는 늘 같아야 하니까","mis":"K2-1-u4-X11"}],"mis":"K2-1-u4-X11","explanation":["같은 목소리로 읽으면 시마다 다른 분위기가 드러나지 않아요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#15','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C9',2,'mc','auto','시를 낭송할 때 알맞은 태도는 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"시를 낭송할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"분위기를 살려 또박또박 읽어요","correct":true},{"t":"장난치며 아무렇게나 읽어요","mis":"K2-1-u4-X15"},{"t":"작게 우물우물 읽어요","mis":"K2-1-u4-X15"}],"explanation":["분위기를 살려 또박또박 읽어야 시가 잘 전해져요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#16','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「강아지가 / 꼬리를 // 흔들어요」","correct":true},{"t":"「강 / 아지가꼬 / 리를 흔들어요」","mis":"K2-1-u4-X13"},{"t":"「강아지가꼬리를흔들어요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#17','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X04','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"은솔 — 「앉다 → [안다]」","correct":true,"mis_target":"K2-1-u4-X04"},{"t":"태민 — 「많다 → [만타]」","mis":"K2-1-u4-X17"},{"t":"아린 — 「맑다 → [막따]」","mis":"K2-1-u4-X17"}],"explanation":["「앉다」는 [안따]라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#18','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「사과가 여덜 개 있다.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"예린 — 「동화책을 읽었다.」","mis":"K2-1-u4-X17"},{"t":"소율 — 「운동장이 넓다.」","mis":"K2-1-u4-X17"}],"explanation":["「여덜」은 소리대로 썼어요. 「여덟」이라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#19','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「책이 없어서 그냥 돌아왔어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"하늘 — 「창가 의자에 앉아 읽었어.」","mis":"K2-1-u4-X17"},{"t":"예린 — 「책을 두 권 빌렸어.」","mis":"K2-1-u4-X17"}],"explanation":["읽고 싶은 책이 많아서 두 권을 빌렸다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["토요일에 언니와 도서관에 갔어요.","창가 의자에 앉아 그림책을 읽었어요.","책 속 바닷가는 모래밭이 넓었어요.","읽고 싶은 책이 많아서 두 권을 빌렸어요."],"title":"도서관 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#20','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"준우 — 「콩콩 뛰는 줄넘기 → 조용한」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"민지 — 「소복소복 눈 오는 밤 → 조용한」","mis":"K2-1-u4-X17"},{"t":"하준 — 「따스한 봄 햇살 → 포근한」","mis":"K2-1-u4-X17"}],"explanation":["「콩콩」은 신나는 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#21','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#22','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"준우 — 「낭송 도중에 크게 하품하며 엎드렸어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"지안 — 「시의 장면을 떠올리며 들었어요.」","mis":"K2-1-u4-X17"},{"t":"하린 — 「끝까지 조용히 들었어요.」","mis":"K2-1-u4-X17"}],"explanation":["크게 하품하며 엎드리면 낭송하는 친구가 속상해요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#23','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C7',4,'mc','auto','친구가 「달밤」을 크고 빠르게 읽었어요. 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X12','K2-1-u4-X11']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"친구가 「달밤」을 크고 빠르게 읽었어요. 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「조용한 시니까 천천히 부드럽게 읽어 보자.」","correct":true},{"t":"「더 크고 더 빠르게 읽으면 좋겠어.」","mis":"K2-1-u4-X12"},{"t":"「소리치며 읽으면 더 잘 들려.」","mis":"K2-1-u4-X11"}],"explanation":["「달밤」은 조용한 시예요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#24','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_b#25','kor',2,1,'u4','','g2_1_kor_u4_review_b','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 조용한 분위기예요. 천천히 부드럽게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["달님이 살며시","창문을 들여다봐요","쉿, 아기가","새근새근 자요"],"title":"달밤"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#1','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"흙","correct":true},{"t":"곰","mis":"K2-1-u4-X05"},{"t":"문","mis":"K2-1-u4-X05"}],"explanation":["「흙」의 받침 자리에는 ㄹ과 ㄱ, 두 글자가 있어요.","「곰」·「문」은 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#2','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C2',1,'mc','auto','「넓다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X04']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「넓다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[널따]","correct":true},{"t":"[넙따]","mis":"K2-1-u4-X03"},{"t":"[널다]","mis":"K2-1-u4-X04"}],"explanation":["ㄼ 받침은 [ㄹ] 소리가 나고 「다」는 [따]로 나서 [널따]예요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#3','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',1,'mc','auto','[여덜]이라고 소리 나는, 일곱 다음의 수를 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[여덜]이라고 소리 나는, 일곱 다음의 수를 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"여덟","correct":true},{"t":"여덜","mis":"K2-1-u4-X01"},{"t":"여덥","mis":"K2-1-u4-X06"}],"explanation":["[여덜]로 들려도 받침 두 글자를 살려 「여덟」이라고 써요.","「여덜」은 소리 나는 대로 썼어요.","「여덥」은 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#4','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C5',1,'mc','auto','「신나는」, 「조용한」, 「포근한」은 시의 무엇을 나타내는 말인가요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"「신나는」, 「조용한」, 「포근한」은 시의 무엇을 나타내는 말인가요?","options":[{"t":"시의 분위기","correct":true},{"t":"시의 제목","mis":"K2-1-u4-X08"},{"t":"시의 글자 수","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「시의 제목」·「시의 글자 수」는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#5','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"포근한","correct":true},{"t":"무서운","mis":"K2-1-u4-X09"},{"t":"쓸쓸한","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 포근한 기분이 느껴져요.","무서운·쓸쓸한 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#6','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C7',1,'mc','auto','씩씩한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"씩씩한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"또렷하고 힘차게","correct":true},{"t":"졸린 듯 작게","mis":"K2-1-u4-X11"},{"t":"울먹이며 느리게","mis":"K2-1-u4-X11"}],"explanation":["씩씩한 분위기는 또렷하고 힘차게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#7','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C10',1,'mc','auto','친구가 낭송할 때 어디를 보며 들으면 좋을까요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 낭송할 때 어디를 보며 들으면 좋을까요?","options":[{"t":"낭송하는 친구","correct":true},{"t":"창밖","mis":"K2-1-u4-X16"},{"t":"내 공책","mis":"K2-1-u4-X16"}],"explanation":["낭송하는 친구를 바라보며 들으면 시가 더 잘 들려요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#8','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C8',1,'ox','auto','한 글자씩 끊어 읽으면 뜻이 가장 잘 드러나요.',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"한 글자씩 끊어 읽으면 뜻이 가장 잘 드러나요.","answer":"X","reason_options":[{"t":"뜻이 이어지는 말끼리 묶어 읽어야 뜻이 드러나니까","correct":true},{"t":"글자를 하나씩 읽어야 또박또박하니까","mis":"K2-1-u4-X13"}],"mis":"K2-1-u4-X13","explanation":["한 글자씩 끊으면 낱말의 뜻이 흐려져요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#9','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"많다","r":"[만타]"},{"l":"읽다","r":"[익따]"},{"l":"짧다","r":"[짤따]"}],"mis":"K2-1-u4-X03","explanation":["「많다」는 [만타]라고 읽어요.","「읽다」는 [익따]라고 읽어요.","「짧다」는 [짤따]라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#10','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',2,'ox','auto','「앉다」는 [안따]로 소리 나니까 「안따」라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「앉다」는 [안따]로 소리 나니까 「안따」라고 써요.","answer":"X","reason_options":[{"t":"소리는 [안따]여도 받침 ㄴ과 ㅈ을 살려 쓰니까","correct":true},{"t":"들리는 소리대로 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「앉다」는 [안따]로 읽지만 「앉다」라고 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#11','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 엄마가 물어보신 것은 무엇인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 엄마가 물어보신 것은 무엇인가요?","options":[{"t":"꿀떡 값","correct":true},{"t":"떡집 이름","mis":"K2-1-u4-X07"},{"t":"시장 가는 길","mis":"K2-1-u4-X07"}],"explanation":["「엄마가 꿀떡 값을 물어보셨어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#12','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"많았어요 · 값 · 없었어요","correct":true},{"t":"많았어요 · 값 · 떡집","mis":"K2-1-u4-X05"},{"t":"시장에 · 값 · 없었어요","mis":"K2-1-u4-X05"}],"explanation":["「많았어요 · 값 · 없었어요」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#13','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C6',2,'mc','auto','씩씩한 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"씩씩한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"힘차게","correct":true},{"t":"새근새근","mis":"K2-1-u4-X10"},{"t":"살금살금","mis":"K2-1-u4-X10"}],"explanation":["「힘차게」는 씩씩한 느낌을 줘요.","「새근새근」·「살금살금」은 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#14','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C7',2,'ox','auto','조용한 시는 천천히, 신나는 시는 조금 빠르게 읽으면 분위기가 살아나요.',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"조용한 시는 천천히, 신나는 시는 조금 빠르게 읽으면 분위기가 살아나요.","answer":"O","reason_options":[{"t":"분위기에 따라 알맞은 빠르기가 다르니까","correct":true},{"t":"모든 시는 같은 빠르기로 읽어야 하니까","mis":"K2-1-u4-X11"}],"mis":"K2-1-u4-X11","explanation":["분위기에 따라 빠르기를 바꾸어 읽어요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#15','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C9',2,'mc','auto','낭송할 시를 고를 때 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"낭송할 시를 고를 때 알맞은 것은 어느 것인가요?","options":[{"t":"읽었을 때 마음에 들고 분위기가 좋은 시","correct":true},{"t":"무조건 가장 긴 시","mis":"K2-1-u4-X15"},{"t":"읽어 보지 않고 아무거나 고른 시","mis":"K2-1-u4-X15"}],"explanation":["마음에 드는 시를 골라야 분위기를 살려 낭송할 수 있어요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#16','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「우리는 / 씩씩한 어린이」","correct":true},{"t":"「우 / 리는씩 / 씩한 어린이」","mis":"K2-1-u4-X13"},{"t":"「우리는씩씩한어린이」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#17','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"민호 — 「넓다 → [넙따]」","correct":true,"mis_target":"K2-1-u4-X03"},{"t":"하린 — 「없다 → [업따]」","mis":"K2-1-u4-X17"},{"t":"지후 — 「짧다 → [짤따]」","mis":"K2-1-u4-X17"}],"explanation":["「넓다」는 [널따]라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#18','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X06','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"은솔 — 「의자에 않았다.」","correct":true,"mis_target":"K2-1-u4-X06"},{"t":"민지 — 「닭이 운다.」","mis":"K2-1-u4-X17"},{"t":"현우 — 「하늘이 맑다.」","mis":"K2-1-u4-X17"}],"explanation":["「않았다」는 받침 짝을 잘못 썼어요. 「앉았다」라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#19','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「떡이 많이 남았어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"로아 — 「떡집 앞에 사람이 많았어.」","mis":"K2-1-u4-X17"},{"t":"하람 — 「엄마가 꿀떡 값을 물으셨어.」","mis":"K2-1-u4-X17"}],"explanation":["동생과 나누어 먹으니 남은 떡이 없었다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["엄마와 시장에 갔어요.","떡집 앞에는 사람이 많았어요.","엄마가 꿀떡 값을 물어보셨어요.","집에 와서 동생과 나누어 먹으니 남은 떡이 없었어요."],"title":"시장 나들이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#20','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"예린 — 「엄마 품처럼 폭신폭신 → 씩씩한」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"지호 — 「톡톡 춤추는 빗방울 → 신나는」","mis":"K2-1-u4-X17"},{"t":"다은 — 「살며시 들여다보는 달님 → 조용한」","mis":"K2-1-u4-X17"}],"explanation":["「엄마 품」·「폭신폭신」은 포근한 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#21','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#22','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"현우 — 「친구 목소리를 흉내 내며 놀렸어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"소율 — 「좋았던 점을 칭찬해 주었어요.」","mis":"K2-1-u4-X17"},{"t":"지우 — 「친구가 멈추었을 때 조용히 기다렸어요.」","mis":"K2-1-u4-X17"}],"explanation":["흉내 내며 놀리면 친구가 속상해요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#23','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C7',4,'mc','auto','「와아, 눈이 온다」를 신나는 분위기가 더 잘 살아나게 읽는 방법은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X13']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「와아, 눈이 온다」를 신나는 분위기가 더 잘 살아나게 읽는 방법은 어느 것인가요?","options":[{"t":"밝고 들뜬 목소리로 조금 빠르게 읽기","correct":true},{"t":"작고 낮은 목소리로 아주 느리게 읽기","mis":"K2-1-u4-X11"},{"t":"한 글자씩 뚝뚝 끊어 읽기","mis":"K2-1-u4-X13"}],"explanation":["밝고 들뜬 목소리가 「와아」의 신나는 느낌을 살려요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#24','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_c#25','kor',2,1,'u4','','g2_1_kor_u4_review_c','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 포근한 분위기예요. 다정하고 따뜻하게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["따스한 햇살이","꽃잎을 살살 쓰다듬어요","엄마 품처럼","폭신폭신 포근해요"],"title":"봄볕"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#1','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C1',1,'mc','auto','받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":1,"concept":"K2-1-u4-C1","difficulty":1,"kind":"mc","stem":"받침 자리에 서로 다른 글자가 두 개 있는 낱말은 어느 것인가요?","options":[{"t":"앉다","correct":true},{"t":"안다","mis":"K2-1-u4-X05"},{"t":"바다","mis":"K2-1-u4-X05"}],"explanation":["「앉」의 받침 자리에는 ㄴ과 ㅈ, 두 글자가 있어요.","「안다」·「바다」는 받침이 하나이거나 없어요.","이런 받침을 겹받침이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#2','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C2',1,'mc','auto','「값」을 바르게 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X03','K2-1-u4-X02']::text[],false,'{"seq":2,"concept":"K2-1-u4-C2","difficulty":1,"kind":"mc","stem":"「값」을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[갑]","correct":true},{"t":"[갓]","mis":"K2-1-u4-X03"},{"t":"[갑ㅅ]","mis":"K2-1-u4-X02"}],"explanation":["ㅄ 받침은 [ㅂ] 소리가 나서 [갑]이에요.","겹받침은 두 글자 가운데 정해진 한 글자의 소리로 읽어요.","뒤 글자가 세게 나는 소리도 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#3','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',1,'mc','auto','[안따]라고 소리 나는, 의자에 엉덩이를 대고 몸을 올려놓는 것을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X06']::text[],false,'{"seq":3,"concept":"K2-1-u4-C3","difficulty":1,"kind":"mc","stem":"[안따]라고 소리 나는, 의자에 엉덩이를 대고 몸을 올려놓는 것을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"앉다","correct":true},{"t":"안따","mis":"K2-1-u4-X01"},{"t":"않다","mis":"K2-1-u4-X06"}],"explanation":["[안따]로 들려도 받침 두 글자를 살려 「앉다」라고 써요.","「안따」는 소리 나는 대로 썼어요.","「않다」는 받침 짝을 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#4','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C5',1,'mc','auto','시를 읽고 포근하다고 느꼈어요. 이렇게 느낀 기분을 무엇이라고 하나요?',ARRAY['K2-1-u4-X08']::text[],false,'{"seq":4,"concept":"K2-1-u4-C5","difficulty":1,"kind":"mc","stem":"시를 읽고 포근하다고 느꼈어요. 이렇게 느낀 기분을 무엇이라고 하나요?","options":[{"t":"분위기","correct":true},{"t":"받침","mis":"K2-1-u4-X08"},{"t":"줄거리","mis":"K2-1-u4-X08"}],"explanation":["분위기는 글이나 시를 읽을 때 느껴지는 기분이에요.","「받침」·「줄거리」는 분위기가 아니에요.","신나는 분위기, 조용한 분위기처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#5','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',1,'mc','auto','시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?',ARRAY['K2-1-u4-X09']::text[],false,'{"seq":5,"concept":"K2-1-u4-C6","difficulty":1,"kind":"mc","stem":"시를 읽고 답해 보세요. 이 시의 분위기는 어느 것인가요?","options":[{"t":"씩씩한","correct":true},{"t":"졸린","mis":"K2-1-u4-X09"},{"t":"슬픈","mis":"K2-1-u4-X09"}],"explanation":["시에 나오는 말과 장면에서 씩씩한 기분이 느껴져요.","졸린·슬픈 느낌을 주는 말은 시에 없어요.","시의 말에 동그라미를 치고 기분을 떠올려요."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#6','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C7',1,'mc','auto','포근한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11']::text[],false,'{"seq":6,"concept":"K2-1-u4-C7","difficulty":1,"kind":"mc","stem":"포근한 분위기의 시를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"다정하고 따뜻하게","correct":true},{"t":"크게 소리 지르며","mis":"K2-1-u4-X11"},{"t":"빠르고 거칠게","mis":"K2-1-u4-X11"}],"explanation":["포근한 분위기는 다정하고 따뜻하게 읽으면 살아나요.","다른 방법은 이 분위기와 어울리지 않아요.","분위기를 먼저 떠올리고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#7','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C10',1,'mc','auto','친구가 낭송하다가 잠깐 멈추었어요. 알맞은 행동은 어느 것인가요?',ARRAY['K2-1-u4-X16']::text[],false,'{"seq":7,"concept":"K2-1-u4-C10","difficulty":1,"kind":"mc","stem":"친구가 낭송하다가 잠깐 멈추었어요. 알맞은 행동은 어느 것인가요?","options":[{"t":"조용히 기다려 주어요","correct":true},{"t":"「빨리 해!」 하고 재촉해요","mis":"K2-1-u4-X16"},{"t":"깔깔 웃어요","mis":"K2-1-u4-X16"}],"explanation":["조용히 기다려 주면 친구가 다시 이어서 낭송할 수 있어요.","다른 행동은 낭송하는 친구를 속상하게 해요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#8','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C8',1,'ox','auto','뜻이 이어지는 말끼리 묶어 한 덩어리씩 띄어 읽어요.',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":8,"concept":"K2-1-u4-C8","difficulty":1,"kind":"ox","stem":"뜻이 이어지는 말끼리 묶어 한 덩어리씩 띄어 읽어요.","answer":"O","reason_options":[{"t":"그래야 듣는 사람이 뜻을 잘 알아들으니까","correct":true},{"t":"덩어리로 묶으면 뜻이 흐려지니까","mis":"K2-1-u4-X13"}],"mis":"K2-1-u4-X13","explanation":["뜻 덩어리로 띄어 읽으면 뜻이 잘 전해져요.","뜻이 이어지는 말끼리 묶어 읽어요.","표시를 따라 읽으면 뜻이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#9','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C2',2,'match','auto','낱말과 바른 소리를 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u4-C2","difficulty":2,"kind":"match","stem":"낱말과 바른 소리를 알맞게 이어 보세요.","pairs":[{"l":"없다","r":"[업따]"},{"l":"젊다","r":"[점따]"},{"l":"여덟","r":"[여덜]"}],"mis":"K2-1-u4-X03","explanation":["「없다」는 [업따]라고 읽어요.","「젊다」는 [점따]라고 읽어요.","「여덟」은 [여덜]이라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#10','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',2,'ox','auto','「여덟」은 [여덜]로 읽지만 쓸 때는 「여덟」이라고 써요.',ARRAY['K2-1-u4-X01']::text[],false,'{"seq":10,"concept":"K2-1-u4-C3","difficulty":2,"kind":"ox","stem":"「여덟」은 [여덜]로 읽지만 쓸 때는 「여덟」이라고 써요.","answer":"O","reason_options":[{"t":"읽는 소리와 쓰는 글자가 다를 수 있으니까","correct":true},{"t":"쓸 때도 소리대로 「여덜」이라고 써야 하니까","mis":"K2-1-u4-X01"}],"mis":"K2-1-u4-X01","explanation":["「여덟」은 [여덜]로 읽고 「여덟」으로 써요.","겹받침은 쓸 때 받침 두 글자를 모두 살려요.","읽을 때와 쓸 때를 가려 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#11','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 아빠와 돗자리를 깔고 앉은 곳은 어디인가요?',ARRAY['K2-1-u4-X07']::text[],false,'{"seq":11,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아빠와 돗자리를 깔고 앉은 곳은 어디인가요?","options":[{"t":"넓은 잔디밭","correct":true},{"t":"모래 놀이터","mis":"K2-1-u4-X07"},{"t":"나무 그늘 의자","mis":"K2-1-u4-X07"}],"explanation":["「넓은 잔디밭에 돗자리를 깔고 앉았어요.」라고 했어요.","다른 내용은 글에 없어요.","글에서 찾아 손가락으로 짚어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 날 아빠와 공원에 갔어요.","넓은 잔디밭에 돗자리를 깔고 앉았어요.","비둘기가 많아서 과자 부스러기를 조금 나누어 주었어요.","신나게 놀다 보니 하루가 짧게 느껴졌어요."],"title":"공원 소풍"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#12','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C4',2,'mc','auto','글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u4-X05']::text[],false,'{"seq":12,"concept":"K2-1-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 글에 나온 겹받침 낱말만 모은 것은 어느 것인가요?","options":[{"t":"맑은 · 넓은 · 앉았어요","correct":true},{"t":"공원에 · 넓은 · 앉았어요","mis":"K2-1-u4-X05"},{"t":"아빠와 · 돗자리를 · 과자","mis":"K2-1-u4-X05"}],"explanation":["「맑은 · 넓은 · 앉았어요」에는 모두 겹받침이 있어요.","다른 묶음에는 겹받침이 없는 낱말이 섞여 있어요.","받침 자리의 글자 수를 세어 봐요."],"asset":{"type":"passage","lines":["하늘이 맑은 날 아빠와 공원에 갔어요.","넓은 잔디밭에 돗자리를 깔고 앉았어요.","비둘기가 많아서 과자 부스러기를 조금 나누어 주었어요.","신나게 놀다 보니 하루가 짧게 느껴졌어요."],"title":"공원 소풍"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#13','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',2,'mc','auto','포근한 분위기가 느껴지는 말은 어느 것인가요?',ARRAY['K2-1-u4-X10']::text[],false,'{"seq":13,"concept":"K2-1-u4-C6","difficulty":2,"kind":"mc","stem":"포근한 분위기가 느껴지는 말은 어느 것인가요?","options":[{"t":"폭신폭신","correct":true},{"t":"쿵쾅쿵쾅","mis":"K2-1-u4-X10"},{"t":"와글와글","mis":"K2-1-u4-X10"}],"explanation":["「폭신폭신」은 포근한 느낌을 줘요.","「쿵쾅쿵쾅」·「와글와글」은 다른 분위기의 말이에요.","소리 내어 따라 하며 느낌을 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#14','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C7',2,'ox','auto','크게 소리 지를수록 어떤 시든 분위기가 잘 살아나요.',ARRAY['K2-1-u4-X12']::text[],false,'{"seq":14,"concept":"K2-1-u4-C7","difficulty":2,"kind":"ox","stem":"크게 소리 지를수록 어떤 시든 분위기가 잘 살아나요.","answer":"X","reason_options":[{"t":"조용하거나 포근한 시는 부드럽게 읽어야 하니까","correct":true},{"t":"목소리가 클수록 언제나 좋으니까","mis":"K2-1-u4-X12"}],"mis":"K2-1-u4-X12","explanation":["목소리 크기도 분위기에 맞추어요.","분위기에 맞게 목소리와 빠르기를 정해요.","시마다 알맞은 읽기 방법이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#15','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C9',2,'mc','auto','연습을 하지 않고 바로 낭송하면 어떻게 될까요?',ARRAY['K2-1-u4-X15']::text[],false,'{"seq":15,"concept":"K2-1-u4-C9","difficulty":2,"kind":"mc","stem":"연습을 하지 않고 바로 낭송하면 어떻게 될까요?","options":[{"t":"분위기를 살려 또박또박 읽기 어려워요","correct":true},{"t":"언제나 더 멋지게 낭송할 수 있어요","mis":"K2-1-u4-X15"},{"t":"시의 분위기가 저절로 살아나요","mis":"K2-1-u4-X15"}],"explanation":["연습해야 분위기에 맞는 목소리를 찾을 수 있어요.","다른 것은 낭송을 잘하는 방법이 아니에요.","고르기 → 연습하기 → 낭송하기를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#16','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C8',2,'mc','auto','알맞게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u4-X13']::text[],false,'{"seq":16,"concept":"K2-1-u4-C8","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「톡톡 빗방울이 / 우산 위에서 // 춤을 춰요」","correct":true},{"t":"「톡 / 톡빗 / 방울이 우산 위에서 춤을 춰요」","mis":"K2-1-u4-X13"},{"t":"「톡톡빗방울이우산위에서춤을춰요」","mis":"K2-1-u4-X13"}],"explanation":["뜻이 이어지는 말끼리 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#17','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C2',3,'error','auto','친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K2-1-u4-X02','K2-1-u4-X17']::text[],false,'{"seq":17,"concept":"K2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 겹받침 낱말을 소리 내어 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"도담 — 「읽다 → [읽따]」","correct":true,"mis_target":"K2-1-u4-X02"},{"t":"서아 — 「젊다 → [점따]」","mis":"K2-1-u4-X17"},{"t":"하준 — 「여덟 → [여덜]」","mis":"K2-1-u4-X17"}],"explanation":["「읽다」는 [익따]라고 읽어요.","겹받침은 정해진 한 글자의 소리로 읽어요.","다른 두 친구는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#18','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',3,'error','auto','받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u4-X01','K2-1-u4-X17']::text[],false,'{"seq":18,"concept":"K2-1-u4-C3","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"태민 — 「바지가 짤바요.」","correct":true,"mis_target":"K2-1-u4-X01"},{"t":"하린 — 「모래가 많다.」","mis":"K2-1-u4-X17"},{"t":"지안 — 「물이 없다.」","mis":"K2-1-u4-X17"}],"explanation":["「짤바요」는 소리대로 썼어요. 「짧아요」라고 써야 해요.","다른 두 친구는 받침 두 글자를 살려 바르게 썼어요.","쓸 때는 겹받침을 모두 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#19','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C4',3,'error','auto','글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u4-X07','K2-1-u4-X17']::text[],false,'{"seq":19,"concept":"K2-1-u4-C4","difficulty":3,"kind":"error","stem":"글을 읽고 내용을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지안 — 「비가 와서 공원에 못 갔어.」","correct":true,"mis_target":"K2-1-u4-X07"},{"t":"도담 — 「잔디밭이 넓었어.」","mis":"K2-1-u4-X17"},{"t":"시우 — 「비둘기에게 과자를 나누어 줬어.」","mis":"K2-1-u4-X17"}],"explanation":["하늘이 맑은 날 공원에 갔다고 했어요.","글에 없는 내용으로 말하면 안 돼요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["하늘이 맑은 날 아빠와 공원에 갔어요.","넓은 잔디밭에 돗자리를 깔고 앉았어요.","비둘기가 많아서 과자 부스러기를 조금 나누어 주었어요.","신나게 놀다 보니 하루가 짧게 느껴졌어요."],"title":"공원 소풍"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#20','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C6',3,'error','auto','시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u4-X10','K2-1-u4-X17']::text[],false,'{"seq":20,"concept":"K2-1-u4-C6","difficulty":3,"kind":"error","stem":"시의 장면과 분위기를 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"하린 — 「가슴 펴고 힘차게 → 조용한」","correct":true,"mis_target":"K2-1-u4-X10"},{"t":"서아 — 「랄랄라 노래하는 웅덩이 → 신나는」","mis":"K2-1-u4-X17"},{"t":"도윤 — 「사뿐사뿐 내려앉는 낙엽 → 조용한」","mis":"K2-1-u4-X17"}],"explanation":["「가슴 펴고 힘차게」는 씩씩한 느낌이에요.","장면에 나오는 말에서 분위기를 느껴요.","다른 두 친구는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#21','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C1',3,'mc','auto','다음 문장에서 겹받침이 있는 글자만 모은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#22','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C10',3,'error','auto','친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?',ARRAY['K2-1-u4-X16','K2-1-u4-X17']::text[],false,'{"seq":22,"concept":"K2-1-u4-C10","difficulty":3,"kind":"error","stem":"친구가 낭송할 때 한 행동이에요. 알맞지 않게 행동한 친구는 누구인가요?","options":[{"t":"민호 — 「낭송 도중에 나도 하겠다며 끼어들었어요.」","correct":true,"mis_target":"K2-1-u4-X16"},{"t":"예린 — 「친구 쪽으로 몸을 돌려 들었어요.」","mis":"K2-1-u4-X17"},{"t":"서윤 — 「끝까지 들은 뒤 손뼉을 쳤어요.」","mis":"K2-1-u4-X17"}],"explanation":["친구가 낭송하는 도중에 끼어들면 안 돼요.","다른 두 친구는 좋은 듣기 태도를 보였어요.","내가 낭송할 때를 떠올려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#23','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C7',4,'mc','auto','「하나 둘 하나 둘 / 살금살금 고양이」처럼 씩씩하다가 조용해지는 시를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u4-X11','K2-1-u4-X12']::text[],false,'{"seq":23,"concept":"K2-1-u4-C7","difficulty":4,"kind":"mc","stem":"「하나 둘 하나 둘 / 살금살금 고양이」처럼 씩씩하다가 조용해지는 시를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"앞줄은 또렷하고 힘차게, 뒷줄은 작고 살며시 읽어요","correct":true},{"t":"두 줄 모두 또렷하고 힘차게 읽어요","mis":"K2-1-u4-X11"},{"t":"두 줄 모두 아주 빠르게 읽어요","mis":"K2-1-u4-X12"}],"explanation":["「살금살금」부터는 조용한 분위기라 목소리를 바꾸어요.","한 가지 방법으로만 읽으면 분위기가 살지 않아요.","분위기에 맞게 목소리와 빠르기를 바꾸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#24','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C3',4,'essay','teacher','다음 문장에서 소리 나는 대로 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u4_review_d#25','kor',2,1,'u4','','g2_1_kor_u4_review_d','unit_review','K2-1-u4-C9',4,'essay','teacher','시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u4-C9","difficulty":4,"kind":"essay","stem":"시를 읽고 답해 보세요. 이 시를 친구들 앞에서 낭송하려고 해요. 시의 분위기를 쓰고, 어떤 목소리와 빠르기로 낭송할지와 낭송할 때 지킬 태도를 써 보세요.","answer_guide":{"answer":"예: 씩씩한 분위기예요. 또렷하고 힘차게 낭송하고, 친구들을 바라보며 바른 자세로 읽을 거예요.","scoring_points":["시의 분위기를 알맞게 썼는가","분위기에 맞는 목소리와 빠르기를 정했는가","또렷하게·친구를 바라보며 같은 낭송 태도를 썼는가"]},"explanation":["분위기.","목소리·빠르기.","낭송 태도."],"asset":{"type":"passage","lines":["하나 둘 하나 둘","발맞춰 걸어요","가슴 펴고 힘차게","우리는 씩씩해요"],"title":"발맞춰 걸어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
